package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.config.ConfigWrites.Write;
import com.ghordrin.bosshealthbar.gamebars.NativeBossBarMode;
import com.ghordrin.bosshealthbar.render.BarFonts;
import com.google.common.collect.ImmutableList;
import java.awt.Font;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.FontType;

@Singleton
public class ConfigMigrations
{
	// The checkbox nativeBossBarMode replaced. Its saved value is moved over on startup.
	static final String OLD_REPLACE_NATIVE_BOSS_BAR_KEY = "replaceNativeBossBar";
	// Remembered what Match boss colors was before the Oldschool theme turned it off. The two now work together,
	// so the key is dropped. Its value isn't restored, which leaves the look unchanged.
	static final String OLD_SAVED_MATCH_BOSS_COLORS_KEY = "oldschoolSavedMatchBossColors";
	// Set once the old default font has been checked for a switch to the new one. Not a config item, so Reset keeps it.
	static final String FONT_DEFAULT_MIGRATED_KEY = "fontDefaultMigrated";
	// Set once a RuneScape font's saved size has been put back to its native size. Not a config item either.
	static final String PIXEL_FONT_SIZE_MIGRATED_KEY = "pixelFontSizeMigrated";
	// Set once the item fonts have been given the look they had with the name's font. Not a config item either.
	static final String ITEM_FONTS_MIGRATED_KEY = "itemFontsMigrated";
	// Set once the fight timer font has been given the kill count's font. Not a config item either.
	static final String FIGHT_TIMER_FONT_MIGRATED_KEY = "fightTimerFontMigrated";

	private static final int OLD_DEFAULT_FONT_SIZE = 17;
	static final List<String> SMALL_TEXT_FONT_KEYS = ImmutableList.of(
		BossHealthBarConfig.COMBAT_LEVEL_FONT_KEY,
		BossHealthBarConfig.HITPOINTS_FONT_KEY,
		BossHealthBarConfig.KILL_COUNT_FONT_KEY,
		BossHealthBarConfig.PARTY_DEFENCE_FONT_KEY,
		BossHealthBarConfig.SPECIAL_ATTACK_COUNTS_FONT_KEY,
		BossHealthBarConfig.WEAKNESS_FONT_KEY,
		BossHealthBarConfig.DRAIN_CAP_FONT_KEY);

	private final ConfigManager configManager;

	@Inject
	ConfigMigrations(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public void migrate()
	{
		migrateReplaceNativeBossBar();
		apply(savedMatchBossColorsWrites(
			configManager.getConfiguration(BossHealthBarConfig.GROUP, OLD_SAVED_MATCH_BOSS_COLORS_KEY)));
		migrateFont(FONT_DEFAULT_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::defaultFontWrites);
		migrateFont(PIXEL_FONT_SIZE_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::pixelFontSizeWrites);
		migrateFont(ITEM_FONTS_MIGRATED_KEY, BossHealthBarConfig.FONT_KEY, ConfigMigrations::itemFontWrites);
		migrateFont(FIGHT_TIMER_FONT_MIGRATED_KEY, BossHealthBarConfig.KILL_COUNT_FONT_KEY,
			ConfigMigrations::fightTimerFontWrites);
	}

	private void migrateReplaceNativeBossBar()
	{
		final String oldSaved = configManager.getConfiguration(BossHealthBarConfig.GROUP, OLD_REPLACE_NATIVE_BOSS_BAR_KEY);
		if (oldSaved == null)
		{
			return;
		}

		apply(replaceNativeBossBarWrites(oldSaved,
			configManager.getConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY)));
	}

	private void migrateFont(String migratedKey, String fontKey, Function<FontType, List<Write>> writes)
	{
		if (ConfigWrites.savedBoolean(configManager, migratedKey) != null)
		{
			return;
		}

		apply(writes.apply(configManager.getConfiguration(BossHealthBarConfig.GROUP, fontKey, FontType.class)));
	}

	private void apply(List<Write> writes)
	{
		for (Write write : writes)
		{
			ConfigWrites.write(configManager, write.getKey(), write.getValue());
		}
	}

	static List<Write> replaceNativeBossBarWrites(String oldSaved, String savedMode)
	{
		final List<Write> writes = new ArrayList<>();
		final NativeBossBarMode mode = nativeBossBarMode(oldSaved, savedMode);
		if (mode != null)
		{
			writes.add(new Write(BossHealthBarConfig.NATIVE_BOSS_BAR_MODE_KEY, mode));
		}
		writes.add(new Write(OLD_REPLACE_NATIVE_BOSS_BAR_KEY, null));
		return writes;
	}

	static List<Write> savedMatchBossColorsWrites(String saved)
	{
		return saved == null
			? Collections.emptyList()
			: Collections.singletonList(new Write(OLD_SAVED_MATCH_BOSS_COLORS_KEY, null));
	}

	// The old "Replace game's boss health bar" checkbox: on replaced the game's bar, off hid ours.
	static NativeBossBarMode fromReplaceSetting(String saved)
	{
		if (saved == null)
		{
			return null;
		}
		return Boolean.parseBoolean(saved) ? NativeBossBarMode.REPLACE : NativeBossBarMode.HIDE_OURS;
	}

	// RuneLite saves the default before the plugin starts, so a saved REPLACE may not be the user's choice.
	static NativeBossBarMode nativeBossBarMode(String oldSaved, String currentSaved)
	{
		final NativeBossBarMode old = fromReplaceSetting(oldSaved);
		if (old == null || (currentSaved != null && !NativeBossBarMode.REPLACE.name().equals(currentSaved)))
		{
			return null;
		}
		return old;
	}

	static List<Write> defaultFontWrites(FontType saved)
	{
		final List<Write> writes = new ArrayList<>();
		if (isOldDefaultFont(saved))
		{
			writes.add(new Write(BossHealthBarConfig.FONT_KEY, FontType.REGULAR));
		}
		writes.add(new Write(FONT_DEFAULT_MIGRATED_KEY, true));
		return writes;
	}

	static List<Write> pixelFontSizeWrites(FontType saved)
	{
		final List<Write> writes = new ArrayList<>();
		final FontType migrated = withNativePixelSize(saved);
		if (migrated != null)
		{
			writes.add(new Write(BossHealthBarConfig.FONT_KEY, migrated));
		}
		writes.add(new Write(PIXEL_FONT_SIZE_MIGRATED_KEY, true));
		return writes;
	}

	// The item fonts are new, so their saved values are only the defaults and can be overwritten. The damage
	// number always used the name's font, whatever it was. The smaller text only needs a change for other
	// fonts, since the RuneScape defaults already match.
	static List<Write> itemFontWrites(FontType name)
	{
		final List<Write> writes = new ArrayList<>();
		if (name != null)
		{
			writes.add(new Write(BossHealthBarConfig.DAMAGE_NUMBER_FONT_KEY, name));
			final FontType small = smallTextFont(name);
			if (small != null)
			{
				for (String key : SMALL_TEXT_FONT_KEYS)
				{
					writes.add(new Write(key, small));
				}
			}
		}
		writes.add(new Write(ITEM_FONTS_MIGRATED_KEY, true));
		return writes;
	}

	// Newer than the item fonts, so it gets its own one-time copy of the kill count font, which that migration set.
	static List<Write> fightTimerFontWrites(FontType killCount)
	{
		final List<Write> writes = new ArrayList<>();
		if (killCount != null)
		{
			writes.add(new Write(BossHealthBarConfig.FIGHT_TIMER_FONT_KEY, killCount));
		}
		writes.add(new Write(FIGHT_TIMER_FONT_MIGRATED_KEY, true));
		return writes;
	}

	// The default before the RuneScape font. RuneLite saves defaults before the plugin starts, so
	// everyone who never changed the font has this saved.
	static boolean isOldDefaultFont(FontType font)
	{
		return font != null
			&& Font.SERIF.equals(font.getFamily())
			&& font.getSize() == OLD_DEFAULT_FONT_SIZE
			&& !font.isBold()
			&& !font.isItalic();
	}

	// The RuneScape fonts used to ignore the saved size, and the font picker keeps the old size when the
	// family changes, so a saved size other than the native one was never seen. Returns null to keep the font.
	static FontType withNativePixelSize(FontType font)
	{
		if (font == null || font.getFamily() == null)
		{
			return null;
		}
		for (FontType pixel : new FontType[]{FontType.REGULAR, FontType.SMALL})
		{
			if (pixel.getFamily().equals(font.getFamily()))
			{
				return font.getSize() == pixel.getSize() ? null : font.withSize(pixel.getSize());
			}
		}
		return null;
	}

	// Before each item had its own font, other fonts drew the smaller text in the name's family at a smaller
	// size, italic like the name but never bold. Returns null for the RuneScape fonts, whose defaults already match.
	public static FontType smallTextFont(FontType name)
	{
		if (name == null || name.getFamily() == null || BarFonts.isRunescapeFont(name.getFamily()))
		{
			return null;
		}
		return new FontType()
			.withFamily(name.getFamily())
			.withSize(BarFonts.smallTextSize(name.getSize()))
			.withItalic(name.isItalic());
	}
}

package com.ghordrin.bosshealthbar.config;

import lombok.Value;
import net.runelite.client.config.ConfigManager;

public final class ConfigWrites
{
	// A null value means unset the key.
	@Value
	static class Write
	{
		String key;
		Object value;
	}

	private ConfigWrites()
	{
	}

	public static void write(ConfigManager configManager, String key, Object value)
	{
		write(configManager, BossHealthBarConfig.GROUP, key, value);
	}

	public static void write(ConfigManager configManager, String group, String key, Object value)
	{
		if (value == null)
		{
			configManager.unsetConfiguration(group, key);
		}
		else
		{
			configManager.setConfiguration(group, key, value);
		}
	}

	static Boolean savedBoolean(ConfigManager configManager, String key)
	{
		final String saved = configManager.getConfiguration(BossHealthBarConfig.GROUP, key);
		return saved != null ? Boolean.valueOf(saved) : null;
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.render.BarPainter;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.border.Border;
import net.runelite.api.Client;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

class FillTexturePickerDialog extends JDialog
{
	private static final int THUMB_SIZE = 48;
	private static final int COLUMNS = 6;
	private static final int TEXTURES_PER_FRAME = 50;
	private static final Border SELECTED_BORDER = BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE, 2);
	private static final Border HOVER_BORDER = BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 2);
	private static final Border IDLE_BORDER = BorderFactory.createEmptyBorder(2, 2, 2, 2);

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final JPanel resultsPanel = new JPanel(new GridLayout(0, COLUMNS, 4, 4));
	private final JLabel statusLabel = new JLabel();

	private JButton selectedButton;
	private volatile int loadGeneration;

	FillTexturePickerDialog(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config)
	{
		super(SwingUtilities.getWindowAncestor(client.getCanvas()), "Choose fill texture");
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;

		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

		final JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setContentPane(content);

		final JButton none = new JButton("None");
		none.setToolTipText("Go back to the plain fill");
		none.setFocusable(false);
		none.addActionListener(e -> selectNone());

		final JButton refresh = new JButton("Refresh");
		refresh.setToolTipText("Read the game's textures again");
		refresh.setFocusable(false);
		refresh.addActionListener(e -> loadTextures());

		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		buttons.setOpaque(false);
		buttons.add(none);
		buttons.add(refresh);

		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());

		final JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		header.add(buttons, BorderLayout.NORTH);
		header.add(statusLabel, BorderLayout.SOUTH);

		// Keeps the grid at its own size in the top left, instead of stretching it over the whole view.
		final JPanel resultsHolder = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		resultsHolder.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resultsPanel.setOpaque(false);
		resultsHolder.add(resultsPanel);
		final JScrollPane scrollPane = new JScrollPane(resultsHolder);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		content.add(header, BorderLayout.NORTH);
		content.add(scrollPane, BorderLayout.CENTER);

		setSize(400, 460);
		setResizable(false);
		setLocationRelativeTo(getOwner());

		loadTextures();
	}

	private void loadTextures()
	{
		statusLabel.setText("Loading...");
		// Decoded in batches over several frames so opening the window doesn't stall the game.
		// A newer load (from Refresh) makes an older one stop.
		final int generation = ++loadGeneration;
		final List<Integer> ids = new ArrayList<>();
		final List<BufferedImage> images = new ArrayList<>();
		final int[] nextId = {0};

		clientThread.invoke(() ->
		{
			if (generation != loadGeneration)
			{
				return true;
			}

			final TextureProvider provider = client.getTextureProvider();
			if (provider != null)
			{
				final Texture[] textures = provider.getTextures();
				final int end = Math.min(textures.length, nextId[0] + TEXTURES_PER_FRAME);
				for (int id = nextId[0]; id < end; id++)
				{
					if (textures[id] == null)
					{
						continue;
					}
					final BufferedImage image = toThumbnail(provider, id);
					if (image != null)
					{
						ids.add(id);
						images.add(image);
					}
				}
				nextId[0] = end;
				if (end < textures.length)
				{
					return false;
				}
			}

			SwingUtilities.invokeLater(() ->
			{
				if (generation == loadGeneration)
				{
					populate(ids, images);
				}
			});
			return true;
		});
	}

	private static BufferedImage toThumbnail(TextureProvider provider, int id)
	{
		final BufferedImage image = BarPainter.decodeTexture(provider, id);
		if (image == null)
		{
			return null;
		}

		final BufferedImage thumb = new BufferedImage(THUMB_SIZE, THUMB_SIZE, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = thumb.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(image, 0, 0, THUMB_SIZE, THUMB_SIZE, null);
		g.dispose();
		return thumb;
	}

	private void populate(List<Integer> ids, List<BufferedImage> images)
	{
		resultsPanel.removeAll();
		selectedButton = null;
		final int currentId = config.fillTextureId();

		for (int i = 0; i < ids.size(); i++)
		{
			final int id = ids.get(i);
			final JButton button = buildButton(id, images.get(i));
			if (id == currentId)
			{
				selectedButton = button;
				button.setBorder(SELECTED_BORDER);
			}
			resultsPanel.add(button);
		}

		statusLabel.setText(ids.isEmpty() ? "No textures loaded yet, try Refresh" : ids.size() + " textures");
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	private JButton buildButton(int textureId, BufferedImage image)
	{
		final JButton button = new JButton(new ImageIcon(image));
		button.setToolTipText("Texture " + textureId);
		button.setPreferredSize(new Dimension(THUMB_SIZE + 4, THUMB_SIZE + 4));
		button.setBorder(IDLE_BORDER);
		button.setContentAreaFilled(false);
		button.setFocusable(false);
		button.addActionListener(e -> select(button, textureId));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(HOVER_BORDER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (button != selectedButton)
				{
					button.setBorder(IDLE_BORDER);
				}
			}
		});
		return button;
	}

	private void select(JButton button, int textureId)
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
		}
		selectedButton = button;
		button.setBorder(SELECTED_BORDER);
		configManager.setConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY, textureId);
	}

	private void selectNone()
	{
		if (selectedButton != null)
		{
			selectedButton.setBorder(IDLE_BORDER);
			selectedButton = null;
		}
		configManager.unsetConfiguration(BossHealthBarConfig.GROUP, BossHealthBarConfig.FILL_TEXTURE_ID_KEY);
	}
}

package com.ghordrin.bosshealthbar.config;

import com.ghordrin.bosshealthbar.config.ConfigWrites.Write;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import net.runelite.client.config.ConfigManager;

// The Oldschool checkbox turns off Rare gold bars and brings it back when it's unticked. Ticking Rare gold
// bars while Oldschool is on unticks Oldschool instead.
public final class OldschoolToggle
{
	// What Rare gold bars was set to before Oldschool turned it off.
	static final String SAVED_RARE_GOLD_BARS_KEY = "oldschoolSavedRareGoldBars";

	@Value
	static class Settings
	{
		boolean oldschool;
		boolean rareGoldBars;
		// Null when nothing is remembered.
		Boolean savedRareGoldBars;
	}

	private OldschoolToggle()
	{
	}

	public static boolean handles(String key)
	{
		return BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key)
			|| BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key);
	}

	// The defaults of the three boxes. Memory goes first so unticking Oldschool restores nothing.
	public static List<Write> resetWrites()
	{
		return Arrays.asList(
			new Write(SAVED_RARE_GOLD_BARS_KEY, null),
			new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false),
			new Write(BossHealthBarConfig.MATCH_BOSS_COLORS_KEY, false),
			new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, true));
	}

	// The remembered keys are cleared before anything is ticked back on, so the change events these
	// writes cause find nothing left to do.
	static List<Write> writes(String key, boolean oldValue, boolean newValue, Settings current)
	{
		if (oldValue == newValue)
		{
			return Collections.emptyList();
		}

		final List<Write> writes = new ArrayList<>();
		if (BossHealthBarConfig.OLDSCHOOL_THEME_KEY.equals(key))
		{
			if (newValue)
			{
				// Switching RuneLite profiles also reports changed keys. Values the new profile already
				// remembers are kept rather than overwritten with the boxes it has turned off.
				if (current.getSavedRareGoldBars() == null)
				{
					writes.add(new Write(SAVED_RARE_GOLD_BARS_KEY, current.isRareGoldBars()));
				}
				writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, false));
			}
			else
			{
				restore(writes, null, current);
			}
		}
		else if (newValue && current.isOldschool() && BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(key))
		{
			restore(writes, key, current);
			writes.add(new Write(BossHealthBarConfig.OLDSCHOOL_THEME_KEY, false));
		}
		return writes;
	}

	private static void restore(List<Write> writes, String skippedKey, Settings current)
	{
		if (current.getSavedRareGoldBars() == null)
		{
			return;
		}
		writes.add(new Write(SAVED_RARE_GOLD_BARS_KEY, null));
		if (!BossHealthBarConfig.RARE_GOLD_BARS_KEY.equals(skippedKey))
		{
			writes.add(new Write(BossHealthBarConfig.RARE_GOLD_BARS_KEY, current.getSavedRareGoldBars()));
		}
	}

	public static void apply(ConfigManager configManager, BossHealthBarConfig config, String key, boolean oldValue,
		boolean newValue)
	{
		applyWrites(configManager, writes(key, oldValue, newValue,
			new Settings(config.oldschoolTheme(), config.rareGoldBars(),
				ConfigWrites.savedBoolean(configManager, SAVED_RARE_GOLD_BARS_KEY))));
	}

	public static void applyWrites(ConfigManager configManager, List<Write> writes)
	{
		// Each write posts its own change event straight away. Handling those again is harmless, since
		// the remembered keys are cleared before anything is turned back on.
		for (Write write : writes)
		{
			ConfigWrites.write(configManager, write.getKey(), write.getValue());
		}
	}
}

package com.ghordrin.bosshealthbar.config;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;

// Opens the custom icon search and the fill texture window.
@Singleton
public class Pickers
{
	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final BossHealthBarConfig config;
	private final ChatboxItemSearch itemSearch;

	// Only touched on the EDT.
	private FillTexturePickerDialog texturePickerDialog;

	@Inject
	Pickers(Client client, ClientThread clientThread, ConfigManager configManager, BossHealthBarConfig config,
		ChatboxItemSearch itemSearch)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.itemSearch = itemSearch;
	}

	// Must be called on the client thread.
	public void openIconPicker()
	{
		itemSearch
			.tooltipText("Custom icon")
			.onItemSelected(itemId -> configManager.setConfiguration(
				BossHealthBarConfig.GROUP, BossHealthBarConfig.CUSTOM_ICON_ITEM_ID_KEY, itemId))
			.build();
	}

	// The item search lives in the chatbox, so it only opens while logged in.
	public void openIconPickerIfLoggedIn()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				openIconPicker();
			}
		});
	}

	public void openFillTexturePicker()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog == null || !texturePickerDialog.isDisplayable())
			{
				texturePickerDialog = new FillTexturePickerDialog(client, clientThread, configManager, config);
			}
			texturePickerDialog.setVisible(true);
			texturePickerDialog.toFront();
		});
	}

	public void close()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (texturePickerDialog != null)
			{
				texturePickerDialog.dispose();
				texturePickerDialog = null;
			}
		});
	}
}

package com.ghordrin.bosshealthbar.data;

import com.ghordrin.bosshealthbar.integrations.HealthIndicatorMarkers;
import com.ghordrin.bosshealthbar.integrations.SpecialAttackCounts;
import java.util.Collections;
import java.util.List;

public final class BarState
{
	public static final float[] NO_PHASE_MARKERS = new float[0];

	public final String name;
	public final int combatLevel;
	public final Health health;
	public final float[] phaseMarkers;
	public final HealthIndicatorMarkers.Marker[] userMarkers;
	public final String killCountKey;
	public final BossStats.Info stats;
	public final List<SpecialAttackCounts.Reading> specialAttacks;
	public final String fightTime;

	public BarState(String name, int combatLevel, Health health, float[] phaseMarkers, HealthIndicatorMarkers.Marker[] userMarkers,
		String killCountKey, BossStats.Info stats, List<SpecialAttackCounts.Reading> specialAttacks, String fightTime)
	{
		this.name = name;
		this.combatLevel = combatLevel;
		this.health = health;
		this.phaseMarkers = phaseMarkers;
		this.userMarkers = userMarkers;
		this.killCountKey = killCountKey;
		this.stats = stats;
		this.specialAttacks = specialAttacks;
		this.fightTime = fightTime;
	}

	// A bar with a name and health but none of the extras.
	public static BarState healthOnly(String name, Health health)
	{
		return new BarState(name, 0, health, NO_PHASE_MARKERS, HealthIndicatorMarkers.NONE, null, null,
			Collections.emptyList(), null);
	}

	public BarState withFightTime(String time)
	{
		return new BarState(name, combatLevel, health, phaseMarkers, userMarkers, killCountKey, stats, specialAttacks,
			time);
	}
}

package com.ghordrin.bosshealthbar.data;

import com.google.common.collect.ImmutableMap;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;

// Elemental weaknesses and how far each boss's defence can be drained in total, from the OSRS Wiki.
// Keyed by NPC ID, since forms and modes of one boss can differ.
public final class BossStats
{
	@Getter
	@RequiredArgsConstructor
	public enum Element
	{
		AIR(ItemID.AIRRUNE),
		WATER(ItemID.WATERRUNE),
		EARTH(ItemID.EARTHRUNE),
		FIRE(ItemID.FIRERUNE);

		private final int runeItemId;
	}

	@Value
	public static class Weakness
	{
		Element element;
		int percent;
	}

	@Value
	public static class Info
	{
		Element weaknessElement;
		public String weaknessText;
		public String drainCapText;
	}

	private static final Builder TABLE = new Builder()
		.weakness(Element.FIRE, 50, NpcID.RAIDS_VESPULA_PORTAL)
		.weakness(Element.AIR, 50, NpcID.BARROWS_AHRIM)
		.weakness(Element.EARTH, 50, NpcID.HYDRABOSS, NpcID.HYDRABOSS_P1_TRANSITION, NpcID.HYDRABOSS_P2_TRANSITION,
			NpcID.HYDRABOSS_P3_TRANSITION, NpcID.HYDRABOSS_4, NpcID.HYDRABOSS_3, NpcID.HYDRABOSS_2,
			NpcID.HYDRABOSS_FINALDEATH)
		.weakness(Element.FIRE, 30, NpcID.AMOXLIATL, NpcID.AMOXLIATL_QUEST)
