		.item(ItemID.WARDENPET_ELIDINIS, HealthBarTheme.ELIDINIS, "Elidinis' Warden")
		.build();

	private KnownBosses()
	{
	}

	public static boolean contains(String name)
	{
		return find(name) != null;
	}

	public static Boss find(String name)
	{
		return name != null ? BOSSES.get(Text.removeTags(name).trim().toLowerCase(Locale.ROOT)) : null;
	}

	private static final class Builder
	{
		private final Map<String, Boss> bosses = new LinkedHashMap<>();
		private final Map<Integer, ThemeColors> palettes = new HashMap<>();
		private final List<String> lastNames = new ArrayList<>();

		Builder sprite(int spriteId, int color, String... names)
		{
			return add(new Icon(false, spriteId), palette(color), names);
		}

		Builder sprite(int spriteId, HealthBarTheme theme, String... names)
		{
			return add(new Icon(false, spriteId), theme.getColors(), names);
		}

		Builder item(int itemId, int color, String... names)
		{
			return add(new Icon(true, itemId), palette(color), names);
		}

		Builder item(int itemId, HealthBarTheme theme, String... names)
		{
			return add(new Icon(true, itemId), theme.getColors(), names);
		}

		public Builder noIcon(int color, String... names)
		{
			return add(null, palette(color), names);
		}

		private ThemeColors palette(int color)
		{
			return palettes.computeIfAbsent(color, rgb -> ThemeColors.fromBase(new Color(rgb)));
		}

		// Applies to every name of the entry before it.
		Builder killCount(String key)
		{
			for (String name : lastNames)
			{
				final Boss boss = bosses.get(name);
				bosses.put(name, new Boss(boss.getIcon(), boss.getColors(), key));
			}
			return this;
		}

		private Builder add(Icon icon, ThemeColors colors, String... names)
		{
			lastNames.clear();
			for (String name : names)
			{
				final String lower = name.toLowerCase(Locale.ROOT);
				Preconditions.checkArgument(bosses.put(lower, new Boss(icon, colors, lower)) == null, name);
				lastNames.add(lower);
			}
			return this;
		}

		Map<String, Boss> build()
		{
			return ImmutableMap.copyOf(bosses);
		}
	}
}

package com.ghordrin.bosshealthbar.data;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

// A list of NPC IDs and names, separated by commas or new lines, where names may use * as a wildcard.
public final class NpcFilter
{
	public enum Match
	{
		NEVER,
		ALSO,
		NONE
	}

	public static final NpcFilter EMPTY = new NpcFilter(new HashSet<>(), new HashSet<>(), new ArrayList<>());

	private final Set<Integer> ids;
	private final Set<String> names;
	private final List<String> patterns;

	private NpcFilter(Set<Integer> ids, Set<String> names, List<String> patterns)
	{
		this.ids = ids;
		this.names = names;
		this.patterns = patterns;
	}

	public static NpcFilter parse(String csv)
	{
		if (csv == null || csv.trim().isEmpty())
		{
			return EMPTY;
		}

		final Set<Integer> ids = new HashSet<>();
		final Set<String> names = new HashSet<>();
		final List<String> patterns = new ArrayList<>();
		for (String entry : Text.fromCSV(csv.replace('\n', ',')))
		{
			if (entry.chars().allMatch(Character::isDigit))
			{
				try
				{
					ids.add(Integer.parseInt(entry));
				}
				catch (NumberFormatException e)
				{
					// Too long to be an NPC ID.
				}
			}
			else if (entry.indexOf('*') >= 0)
			{
				patterns.add(entry);
			}
			else
			{
				names.add(Text.standardize(entry));
			}
		}
		return new NpcFilter(ids, names, patterns);
	}

	public boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty() && patterns.isEmpty();
	}

	// The name must already be standardized.
	boolean matches(String name, int id, int currentId)
	{
		if (ids.contains(id) || ids.contains(currentId) || names.contains(name))
		{
			return true;
		}
		for (String pattern : patterns)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}

	static Match check(NpcFilter never, NpcFilter also, String name, int id, int currentId)
	{
		if (never.matches(name, id, currentId))
		{
			return Match.NEVER;
		}
		return also.matches(name, id, currentId) ? Match.ALSO : Match.NONE;
	}

	// The lists are checked every frame, so the answer is kept for the last NPC, name and form.
	public static final class LastMatch
	{
		private NPC npc;
		private String name;
		private int currentId;
		private Match match = Match.NONE;

		public Match get(NPC npc, NpcFilter never, NpcFilter also)
		{
			final String name = npc.getName();
			final int currentId = NpcUtil.currentId(npc);
			if (npc != this.npc || currentId != this.currentId || !name.equals(this.name))
			{
				this.npc = npc;
				this.name = name;
				this.currentId = currentId;
				match = check(never, also, Text.standardize(name), NpcUtil.baseId(npc), currentId);
			}
			return match;
		}

		public void clear()
		{
			npc = null;
		}
	}
}

package com.ghordrin.bosshealthbar.data;

import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;

public final class NpcUtil
{
	private NpcUtil()
	{
	}

	// Only an NPC counts, a player is never attackable here.
	public static boolean isAttackable(Actor actor)
	{
		return actor instanceof NPC && isAttackable((NPC) actor);
	}

	public static boolean isAttackable(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			return false;
		}
		for (String action : composition.getActions())
		{
			if ("Attack".equals(action))
			{
				return true;
			}
		}
		return false;
	}

	public static int size(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		return composition != null ? composition.getSize() : 0;
	}

	public static int currentId(NPC npc)
	{
		final NPCComposition composition = npc.getTransformedComposition();
		return composition != null ? composition.getId() : npc.getId();
	}

	// The game's boss bar tracks the base NPC ID, not the ID of the current form.
	public static int baseId(NPC npc)
	{
		final NPCComposition composition = npc.getComposition();
		return composition != null ? composition.getId() : -1;
	}
}

package com.ghordrin.bosshealthbar.data;

import com.ghordrin.bosshealthbar.theme.ThemeColors;
import com.google.common.base.Strings;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.client.util.Text;

// What the bar needs to know about the current opponent beyond its health: the name to show, the kill count key,
// the boss stats, and the icon and colors of a known boss. Looked up once per opponent and kept until it changes.
@Singleton
public class OpponentInfo
{
	private Actor actor;
	private int npcId = -1;
	private String name;
	private String killCountKey;
	private BossStats.Info stats;
	private KnownBosses.Icon bossIcon;
	private ThemeColors bossColors;

	public String name()
	{
		return name;
	}

	public String killCountKey()
	{
		return killCountKey;
	}

	public BossStats.Info stats()
	{
		return stats;
	}

	public KnownBosses.Icon bossIcon()
	{
		return bossIcon;
	}

	public ThemeColors bossColors()
	{
		return bossColors;
	}

	public void reset()
	{
		actor = null;
	}

	public void update(Actor opponent)
	{
		final NPCComposition composition = opponent instanceof NPC
			? ((NPC) opponent).getTransformedComposition() : null;
		final int id = composition != null ? composition.getId() : -1;
		if (opponent == actor && id == npcId)
		{
			return;
		}

		String shown = Text.removeTags(opponent.getName());
		boolean complete = true;
		bossIcon = null;
		bossColors = null;
		killCountKey = null;
		stats = null;
		if (opponent instanceof NPC)
		{
			final KnownBosses.Boss boss = KnownBosses.find(shown);
			if (boss != null)
			{
				bossIcon = boss.getIcon();
				bossColors = boss.getColors();
				killCountKey = boss.getKillCountKey();
			}
			stats = BossStats.info(NpcUtil.currentId((NPC) opponent));
			if (composition != null)
			{
				final String longName = composition.getStringValue(ParamID.NPC_HP_NAME);
				if (!Strings.isNullOrEmpty(longName) && longName.contains(shown))
				{
					shown = longName;
				}
			}
			else
			{
				complete = false;
			}
		}

		name = shown;
		actor = complete ? opponent : null;
		npcId = id;
	}
}

