// Writes the debug log, with the plugin's state and settings, to a text file for bug reports.
@Slf4j
@Singleton
public class DebugExport
{
	private static final int KEEP_FILES = 10;
	private static final String FILE_PREFIX = "boss-health-bar-debug-";
	private static final String FILE_SUFFIX = ".txt";
	private static final Pattern FILE_NAME = Pattern.compile("boss-health-bar-debug-\\d{8}-\\d{6}\\.txt");
	private static final DateTimeFormatter FILE_TIME = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");
	private static final DateTimeFormatter HEADER_TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
	private static final String CONFIG_PREFIX = BossHealthBarConfig.GROUP + ".";
	private static final int MAX_VALUE_LENGTH = 200;
	private static final String[] RELATED_PLUGINS = {
		"Boss Health Indicators",
		"Opponent Information",
		"Party Defence Tracker",
		"Better Party Defence",
		"Special Attack Counter",
		"Health Threshold Indicators",
	};

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final PluginManager pluginManager;
	private final ChatMessageManager chatMessageManager;
	private final ScheduledExecutorService executor;
	private final DebugLog debugLog;
	private final BossHealthBarPlugin plugin;
	private final OpponentTracker opponentTracker;
	private final GameBossBar gameBossBar;
	private final TobBossBar tobBossBar;
	private final PillarBars pillarBars;
	private final FightTimer fightTimer;

	@Inject
	DebugExport(Client client, ClientThread clientThread, ConfigManager configManager, PluginManager pluginManager,
		ChatMessageManager chatMessageManager, ScheduledExecutorService executor, DebugLog debugLog,
		BossHealthBarPlugin plugin, OpponentTracker opponentTracker, GameBossBar gameBossBar, TobBossBar tobBossBar,
		PillarBars pillarBars, FightTimer fightTimer)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.pluginManager = pluginManager;
		this.chatMessageManager = chatMessageManager;
		this.executor = executor;
		this.debugLog = debugLog;
		this.plugin = plugin;
		this.opponentTracker = opponentTracker;
		this.gameBossBar = gameBossBar;
		this.tobBossBar = tobBossBar;
		this.pillarBars = pillarBars;
		this.fightTimer = fightTimer;
	}

	public void save()
	{
		clientThread.invoke(() ->
		{
			final LocalDateTime now = LocalDateTime.now();
			final String text = DebugLog.render(header(now), debugLog.snapshot());
			executor.execute(() -> write(fileName(now), text));
		});
	}

	private void write(String fileName, String text)
	{
		try
		{
			final Filepath directory = plugin.dataDirectory();
			directory.createDirectories();
			final Filepath file = directory.joinSegment(fileName);
			file.write(text.getBytes(StandardCharsets.UTF_8));
			removeOldFiles(directory);
			chat("Debug log saved to .runelite/plugin-data/" + BossHealthBarPlugin.INTERNAL_NAME + "/" + fileName);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Couldn't save the debug log", e);
			chat("Couldn't save the debug log.");
		}
	}

	private void removeOldFiles(Filepath directory) throws IOException
	{
		final List<Filepath> files;
		try (Stream<Filepath> walk = directory.walk(1))
		{
			files = walk.filter(Filepath::isFile).collect(Collectors.toList());
		}
		final List<String> names = new ArrayList<>();
		for (Filepath file : files)
		{
			names.add(file.getFileName());
		}
		for (String name : namesToDelete(names, KEEP_FILES))
		{
			directory.joinSegment(name).deleteIfExists();
		}
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private List<String> header(LocalDateTime now)
	{
		final List<String> lines = new ArrayList<>();
		lines.add(BossHealthBarPlugin.NAME + " debug log");
		lines.add("Saved at " + HEADER_TIME.format(now) + " (local time)");
		lines.add("Plugin " + BossHealthBarPlugin.VERSION);
		lines.add("RuneLite " + RuneLiteProperties.getVersion());
		lines.add("Client revision " + client.getRevision());
		lines.add("Game state " + client.getGameState());
		lines.add("Game tick " + client.getTickCount());

		lines.add("");
		lines.add("Related plugins");
		for (String name : RELATED_PLUGINS)
		{
			lines.add("  " + name + ": " + pluginState(name));
		}

		lines.add("");
		lines.add("Current state");
		lines.add("  Opponent: " + DebugLog.describe(opponentTracker.getOpponent()));
		final int trackedId = gameBossBar.trackedNpcId();
		lines.add("  Game boss bar: " + (trackedId == -1 ? "none"
			: "NPC id " + trackedId + ", health " + gameBossBar.health() + "/" + gameBossBar.maxHealth())
			+ ", hidden " + gameBossBar.isHidden());
		lines.add("  Raid boss bar: " + DebugLog.describe(tobBossBar.cachedBoss()) + ", hidden " + tobBossBar.isHidden());
		lines.add("  Pillar bars: present " + pillarBars.isSeen() + ", hidden " + pillarBars.isHidingGameBars()
			+ ", shown " + pillarBars.isShown());
		final String fightTime = fightTimer.getText();
		lines.add("  Fight timer: " + (fightTime != null ? fightTime : "none"));

		lines.add("");
		lines.add("Settings");
		final List<String> keys = new ArrayList<>(configManager.getConfigurationKeys(CONFIG_PREFIX));
		Collections.sort(keys);
		for (String fullKey : keys)
		{
			final String key = fullKey.substring(CONFIG_PREFIX.length());
			lines.add("  " + key + " = "
				+ DebugLog.cut(configManager.getConfiguration(BossHealthBarConfig.GROUP, key), MAX_VALUE_LENGTH));
		}
		return lines;
	}

	private String pluginState(String name)
	{
		final Plugin other = PluginState.find(pluginManager, name);
		if (other == null)
		{
			return "not installed";
		}
		return pluginManager.isPluginActive(other) ? "on" : "off";
	}

	static String fileName(LocalDateTime time)
	{
		return FILE_PREFIX + FILE_TIME.format(time) + FILE_SUFFIX;
	}

	// The time in the name sorts the files oldest first. Only files with our own name pattern are touched.
	static List<String> namesToDelete(List<String> names, int keep)
	{
		final List<String> ours = names.stream()
			.filter(name -> FILE_NAME.matcher(name).matches())
			.sorted()
			.collect(Collectors.toList());
		return ours.size() <= keep ? Collections.emptyList() : ours.subList(0, ours.size() - keep);
	}
}

package com.ghordrin.bosshealthbar.debug;

import com.ghordrin.bosshealthbar.data.NpcUtil;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import org.slf4j.helpers.MessageFormatter;

// The plugin's recent activity, kept in memory so it can be saved for a bug report.
@Slf4j
@Singleton
public class DebugLog
{
	static final int CAPACITY = 1000;
	static final int NO_TICK = -1;
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss.SSS");

	public static final class Entry
	{
		final long millis;
		final int tick;
		public final String message;
		public final int repeats;

		public Entry(long millis, int tick, String message, int repeats)
		{
			this.millis = millis;
			this.tick = tick;
			this.message = message;
			this.repeats = repeats;
		}
	}

	private final Client client;
	private final Deque<Entry> entries = new ArrayDeque<>();

	@Inject
	public DebugLog(Client client)
	{
		this.client = client;
	}

	public void add(String format, Object... args)
	{
		final String message = MessageFormatter.arrayFormat(format, args).getMessage();
		log.debug("{}", message);
		final int tick = client != null && client.isClientThread() ? client.getTickCount() : NO_TICK;
		add(System.currentTimeMillis(), tick, message);
	}

	public synchronized void add(long millis, int tick, String message)
	{
		final Entry last = entries.peekLast();
		if (last != null && last.message.equals(message))
		{
			entries.pollLast();
			entries.addLast(new Entry(millis, tick, message, last.repeats + 1));
			return;
		}
		if (entries.size() >= CAPACITY)
		{
			entries.pollFirst();
		}
		entries.addLast(new Entry(millis, tick, message, 1));
	}

	public synchronized List<Entry> snapshot()
	{
		return new ArrayList<>(entries);
	}

	// Players are never named, so nothing about other people ends up in a saved log.
	public static String describe(Actor actor)
	{
		if (actor == null)
		{
			return "none";
		}
		if (actor instanceof Player)
		{
			return "a player";
		}
		if (actor instanceof NPC)
		{
			final NPC npc = (NPC) actor;
			return describeNpc(npc.getName(), npc.getId(), NpcUtil.currentId(npc), npc.getIndex());
		}
		return "another actor";
	}

	static String describeNpc(String name, int id, int form, int index)
	{
		return name + " (id " + id + ", form " + form + ", index " + index + ")";
	}

	static String render(List<String> header, List<Entry> entries)
	{
		return render(header, entries, ZoneId.systemDefault());
	}

	static String render(List<String> header, List<Entry> entries, ZoneId zone)
	{
		final StringBuilder builder = new StringBuilder();
		for (String line : header)
		{
			builder.append(line).append('\n');
		}
		builder.append('\n').append("Recent events (oldest first)").append('\n');
		for (Entry entry : entries)
		{
			builder.append(TIME.format(Instant.ofEpochMilli(entry.millis).atZone(zone)))
				.append("  tick ").append(entry.tick == NO_TICK ? "-" : Integer.toString(entry.tick))
				.append("  ").append(entry.message);
			if (entry.repeats > 1)
			{
				builder.append(" (x ").append(entry.repeats).append(')');
			}
			builder.append('\n');
		}
		return builder.toString();
	}

	public static String cut(String value, int max)
	{
		if (value == null)
		{
			return "null";
		}
		return value.length() <= max ? value : value.substring(0, max) + "...";
	}
}

package com.ghordrin.bosshealthbar.gamebars;

import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.data.NpcUtil;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import com.ghordrin.bosshealthbar.render.BarAnimation;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
public class GameBossBar
{
	// Set to 1 on NPCs whose game boss bar only shows a percentage. No gameval constant exists for it.
	private static final int PARAM_HP_PERCENTAGE_ONLY = 2289;

	// The layer holding only the bar, since the game mounts other HUDs, like pillar health bars, in the same interface.
	private static final int GAME_BAR = InterfaceID.HpbarHud.HPDODGER;

	private static final int[] PHASE_MARKER_VARBITS = {
		VarbitID.HPBAR_HUD_LOWER_THRESHOLD,
		VarbitID.HPBAR_HUD_UPPER_THRESHOLD,
		VarbitID.HPBAR_HUD_HP_1,
		VarbitID.HPBAR_HUD_HP_2,
	};

	private final Client client;
	private final DebugLog debugLog;
	private final HiddenWidget gameBar;

	private NPC npc;
	private int searchedId = -1;
	private int replacedId = -1;
	private int loggedTrackedId = -1;
	private int healthSeenId = -1;
	private int loggedZeroId = -1;

	private int percentOnlyNpcId = -1;
	private boolean percentOnly;

	private final int[] phaseMarkerValues = new int[PHASE_MARKER_VARBITS.length];
	private int phaseMarkerMaxHealth;
	private float[] phaseMarkers = BarState.NO_PHASE_MARKERS;

	@Inject
	GameBossBar(Client client, DebugLog debugLog)
	{
		this.client = client;
		this.debugLog = debugLog;
		this.gameBar = new HiddenWidget(client, debugLog, GAME_BAR);
	}

	public void onGameTick()
	{
		final int trackedId = trackedNpcId();
		if (trackedId != loggedTrackedId)
		{
			loggedTrackedId = trackedId;
			if (trackedId == -1)
			{
				debugLog.add("Game boss bar tracks nothing");
			}
			else
			{
				debugLog.add("Game boss bar tracks NPC id {} (health {}/{})", trackedId, health(), maxHealth());
			}
		}
		if (trackedId != -1 && trackedId != loggedZeroId && !hasHealth())
		{
			loggedZeroId = trackedId;
			debugLog.add("Game boss bar reads 0 for NPC id {} before its health arrived, ignored", trackedId);
		}
	}

	public int trackedNpcId()
	{
		if (client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS_DISABLED) != 0)
		{
			return -1;
		}
		return client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
	}

	public boolean isTracking(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}
		final int trackedId = trackedNpcId();
		return trackedId != -1 && NpcUtil.baseId((NPC) actor) == trackedId;
	}

	public NPC findNpc(Actor opponent)
	{
		final int trackedId = trackedNpcId();
		if (trackedId == -1)
		{
			npc = null;
			searchedId = -1;
			return null;
		}

		if (isTracking(opponent))
		{
			npc = (NPC) opponent;
			return npc;
		}

		final Player player = client.getLocalPlayer();
		final Actor target = player != null ? player.getInteracting() : null;
		if (isTracking(target))
		{
			npc = (NPC) target;
			return npc;
		}

		if (npc != null && NpcUtil.baseId(npc) == trackedId)
		{
			return npc;
		}

		if (npc == null && trackedId == searchedId)
		{
			return null;
		}

		npc = null;
		searchedId = trackedId;
		for (NPC candidate : client.getTopLevelWorldView().npcs())
		{
			if (NpcUtil.baseId(candidate) == trackedId)
			{
				npc = candidate;
				break;
			}
		}
		return npc;
	}

	public void onNpcSpawned()
	{
		searchedId = -1;
	}

	public void onNpcDespawned(NPC despawned)
	{
		if (despawned == npc)
		{
			npc = null;
		}
	}

	public boolean update(Actor opponent, boolean replaceEnabled, boolean opponentGetsBar)
	{
		final Widget bar = gameBar.widget();
		if (bar == null)
		{
			gameBar.forget();
			return false;
		}

		boolean replace = false;
		if (replaceEnabled)
		{
			// An opponent without our bar, such as one on the Never show for list, keeps the game's bar.
			if (isTracking(opponent))
			{
				replace = opponentGetsBar;
				replacedId = trackedNpcId();
			}
			else
			{
				// After the boss despawns, the game's bar can stay up on it while the defeat animation
				// plays, so keep it hidden until it tracks a different NPC.
				replace = replacedId != -1 && trackedNpcId() == replacedId;
			}
		}

		if (replace)
		{
			// replace is only set while the game's bar tracks replacedId.
			gameBar.hide(bar, "Game boss bar hidden (tracked id {})", replacedId);
		}
		else
		{
			replacedId = -1;
			restore();
		}
		return replace;
	}

	private void restore()
	{
		if (!gameBar.isHidden() || trackedNpcId() == -1)
		{
			return;
		}
		release();
	}

	private void release()
	{
		gameBar.release("Game boss bar shown again");
	}

	public void reset()
	{
		// Nothing else unhides the bar, so do it here even when the game no longer tracks an NPC.
		release();
		npc = null;
		searchedId = -1;
		replacedId = -1;
		loggedTrackedId = -1;
		healthSeenId = -1;
		loggedZeroId = -1;
	}

	public boolean isHidden()
	{
		return gameBar.isHidden();
	}

	public int maxHealth()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
	}

	public int health()
	{
		return client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
	}

	// Right after the bar moves to another NPC it can read 0 before that NPC's health arrives, so a 0 only
	// counts once the bar has shown health above 0 for the NPC it tracks.
	public boolean hasHealth()
	{
		final int trackedId = trackedNpcId();
		if (health() > 0)
		{
			healthSeenId = trackedId;
			return true;
		}
		return trackedId != -1 && trackedId == healthSeenId;
	}

	public boolean isPercentOnly()
	{
		final int npcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
		if (npcId != percentOnlyNpcId)
		{
			final NPCComposition composition = npcId != -1 ? client.getNpcDefinition(npcId) : null;
			percentOnly = composition != null && composition.getIntValue(PARAM_HP_PERCENTAGE_ONLY) == 1;
			percentOnlyNpcId = npcId;
		}
		return percentOnly;
	}

	public float[] phaseMarkers(int maxHealth)
	{
		boolean changed = maxHealth != phaseMarkerMaxHealth;
		for (int i = 0; i < PHASE_MARKER_VARBITS.length; i++)
		{
			final int value = client.getVarbitValue(PHASE_MARKER_VARBITS[i]);
			if (value != phaseMarkerValues[i])
			{
				phaseMarkerValues[i] = value;
				changed = true;
			}
		}
		if (!changed)
		{
			return phaseMarkers;
		}
		phaseMarkerMaxHealth = maxHealth;

		float[] markers = null;
		int count = 0;
		for (int value : phaseMarkerValues)
		{
			if (value > 0 && value <= maxHealth + 1)
			{
				if (markers == null)
				{
					markers = new float[PHASE_MARKER_VARBITS.length];
				}
				markers[count++] = markerFraction(value, maxHealth);
			}
		}
		phaseMarkers = markers == null ? BarState.NO_PHASE_MARKERS : Arrays.copyOf(markers, count);
		return phaseMarkers;
	}

	// Same placement as the game's own bar: a marker for value v sits at (v - 1) / max health.
	static float markerFraction(int value, int maxHealth)
	{
		return BarAnimation.clamp01((value - 1) / (float) maxHealth);
	}
}

package com.ghordrin.bosshealthbar.gamebars;

import com.ghordrin.bosshealthbar.debug.DebugLog;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

// A game widget hidden while this plugin draws its own version, and shown again when it stops.
class HiddenWidget
{
	private final Client client;
	private final DebugLog debugLog;
	private final int widgetId;

	private boolean hidden;

	HiddenWidget(Client client, DebugLog debugLog, int widgetId)
	{
		this.client = client;
		this.debugLog = debugLog;
		this.widgetId = widgetId;
	}

	Widget widget()
	{
		return client.getWidget(widgetId);
	}

	void hide(Widget widget, String message, Object... args)
	{
		if (!widget.isSelfHidden())
		{
			widget.setHidden(true);
			if (!hidden)
			{
				debugLog.add(message, args);
			}
			hidden = true;
		}
	}

	void release(String message)
	{
		release(message, true);
	}

	void release(String message, boolean unhide)
	{
		if (hidden)
		{
			debugLog.add(message);
			final Widget widget = widget();
			if (widget != null && unhide)
			{
				widget.setHidden(false);
			}
		}
		hidden = false;
	}

	// For when the widget is gone, so there is nothing left to show again.
	void forget()
	{
		hidden = false;
	}

	boolean isHidden()
	{
		return hidden;
	}
}

