package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarTextPainter.DAMAGE_NUMBER;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.DRAIN_CAP;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.FIGHT_TIMER;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.HITPOINTS;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.ITEM_COUNT;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.KILL_COUNT;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.MAGIC_DEFENCE;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.NAME;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.PARTY_DEFENCE;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.SPECIAL_ATTACKS;
import static com.ghordrin.bosshealthbar.render.BarTextPainter.WEAKNESS;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.google.common.annotations.VisibleForTesting;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.config.FontType;
import net.runelite.client.ui.FontManager;

public class BarFonts
{
	private static final int REFERENCE_FONT_SIZE = 16;
	private static final int MIN_FONT_SIZE = 8;
	private static final int MAX_FONT_SIZE = 40;
	private static final float SMALL_TEXT_SCALE = 0.72f;
	private static final int HEADER_HEIGHT = 24;
	private static final int HEADER_BASELINE_GAP = 6;
	private static final int FOOTER_HEIGHT = 16;

	private final BossHealthBarConfig config;

	// Each font's metrics, measured with its own smoothing, which changes the glyph widths.
	private final FontMetrics[] metrics = new FontMetrics[ITEM_COUNT];
	private FontMetrics levelMetrics;

	private final FontType[] requestedFonts = new FontType[ITEM_COUNT];
	private final ItemFont[] itemFonts = new ItemFont[ITEM_COUNT];
	private final ItemFont levelItemFont = new ItemFont();
	private final Font[] fonts = new Font[ITEM_COUNT];
	private final boolean[] pixelFonts = new boolean[ITEM_COUNT];
	private Font levelFont;
	private boolean smoothText;
	private boolean measured;

	// How far each item's text reaches above and below the shared baseline of its row.
	private final int[] itemAbove = new int[ITEM_COUNT];
	private final int[] itemBelow = new int[ITEM_COUNT];
	private int levelAbove;
	private int levelBelow;

	BarFonts(BossHealthBarConfig config)
	{
		this.config = config;
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			itemFonts[item] = new ItemFont();
		}
		itemFonts[MAGIC_DEFENCE] = itemFonts[PARTY_DEFENCE];
	}

	void updateFonts()
	{
		final boolean smooth = config.smoothText();
		readItemFonts(config, requestedFonts);
		boolean changed = !measured || smooth != smoothText;
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			if (item != MAGIC_DEFENCE)
			{
				changed |= itemFonts[item].update(requestedFonts[item], defaultFont(item));
			}
		}
		changed |= levelItemFont.update(config.combatLevelFont(), FontType.SMALL);
		if (!changed)
		{
			return;
		}

		smoothText = smooth;
		for (int item = 0; item < ITEM_COUNT; item++)
		{
			fonts[item] = itemFonts[item].font;
			pixelFonts[item] = itemFonts[item].pixel;
		}
		levelFont = levelItemFont.font;
		measureItems();
		measured = true;
	}

	@VisibleForTesting
	static void readItemFonts(BossHealthBarConfig config, FontType[] fonts)
	{
		fonts[NAME] = config.font();
		fonts[HITPOINTS] = config.hitpointsFont();
		fonts[DAMAGE_NUMBER] = config.damageNumberFont();
		fonts[FIGHT_TIMER] = config.fightTimerFont();
		fonts[KILL_COUNT] = config.killCountFont();
		fonts[PARTY_DEFENCE] = config.partyDefenceFont();
		fonts[MAGIC_DEFENCE] = fonts[PARTY_DEFENCE];
		fonts[SPECIAL_ATTACKS] = config.specialAttackCountsFont();
		fonts[WEAKNESS] = config.weaknessFont();
		fonts[DRAIN_CAP] = config.drainCapFont();
	}

	private static FontType defaultFont(int item)
	{
		switch (item)
		{
			case NAME:
				return BossHealthBarConfig.DEFAULT_FONT;
			case DAMAGE_NUMBER:
				return FontType.REGULAR;
			default:
				return FontType.SMALL;
		}
	}

	// The RuneScape fonts are bitmaps, so they're never smoothed.
	public static boolean isRunescapeFont(String family)
	{
		return family.equals(FontManager.getRunescapeFont().getFamily())
			|| family.equals(FontManager.getRunescapeSmallFont().getFamily())
			|| family.equals(FontManager.getRunescapeBoldFont().getFamily());
	}

	static int clampFontSize(int size)
	{
		return Math.max(MIN_FONT_SIZE, Math.min(MAX_FONT_SIZE, size));
	}

	// What the smaller text used to be with other fonts, before each item had its own font.
	public static int smallTextSize(int nameSize)
	{
		return Math.max(MIN_FONT_SIZE, Math.round(clampFontSize(nameSize) * SMALL_TEXT_SCALE));
	}

	@VisibleForTesting
	static int scaledToFont(int height, int fontSize)
	{
		return Math.round(height * (fontSize / (float) REFERENCE_FONT_SIZE));
	}

	// The name and damage number get a taller row with a gap under the baseline.
	@VisibleForTesting
	static int largeAbove(int fontSize)
	{
		return scaledToFont(HEADER_HEIGHT, fontSize) - largeBelow(fontSize);
	}

	@VisibleForTesting
	static int largeBelow(int fontSize)
	{
		return scaledToFont(HEADER_BASELINE_GAP, fontSize);
	}

	// Other fonts keep the row height they had when the small text was sized from the name font: as tall as
	// the name font when it's still the name's small text, else about that.
	@VisibleForTesting
	static int smallRowHeight(int fontSize, boolean pixel, String family, String nameFamily, int nameSize)
	{
		if (pixel)
		{
			return scaledToFont(FOOTER_HEIGHT, fontSize);
		}
		if (family.equals(nameFamily) && fontSize == smallTextSize(nameSize))
		{
			return clampFontSize(nameSize);
		}
		return Math.round(fontSize / SMALL_TEXT_SCALE);
	}

	private int smallRowHeight(ItemFont font)
	{
		final ItemFont name = itemFonts[NAME];
		return smallRowHeight(font.size, font.pixel, font.family, name.family, name.size);
	}

	@VisibleForTesting
	static int smallBelow(int rowHeight, int above)
	{
		return Math.max(0, rowHeight - above);
	}

	// Measured off screen with the same hints as the overlay, which only translates, so the metrics are
	// known before the overlay lays out its frame and are reused for every frame.
	private void measureItems()
	{
		final Graphics2D scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try
		{
			applyTextHints(scratch);
			for (int item = 0; item < ITEM_COUNT; item++)
			{
				setTextAntialiasing(scratch, pixelFonts[item]);
				metrics[item] = scratch.getFontMetrics(fonts[item]);
				final int size = fonts[item].getSize();
				if (item == NAME || item == DAMAGE_NUMBER)
				{
					itemAbove[item] = largeAbove(size);
					itemBelow[item] = largeBelow(size);
				}
				else
				{
					itemAbove[item] = metrics[item].getAscent() + 1;
					itemBelow[item] = smallBelow(smallRowHeight(itemFonts[item]), itemAbove[item]);
				}
			}
			setTextAntialiasing(scratch, levelItemFont.pixel);
			levelMetrics = scratch.getFontMetrics(levelFont);
			levelAbove = levelMetrics.getAscent() + 1;
			levelBelow = smallBelow(smallRowHeight(levelItemFont), levelAbove);
		}
		finally
		{
			scratch.dispose();
		}
	}

	@VisibleForTesting
	Font font(int item)
	{
		return fonts[item];
	}

	@VisibleForTesting
	Font levelFont()
	{
		return levelFont;
	}

	FontMetrics metrics(int item)
	{
		return metrics[item];
	}

	FontMetrics levelMetrics()
	{
		return levelMetrics;
	}

	int above(int item)
	{
		return itemAbove[item];
	}

	int below(int item)
	{
		return itemBelow[item];
	}

	int levelAbove()
	{
		return levelAbove;
	}

	int levelBelow()
	{
		return levelBelow;
	}

	private void setTextAntialiasing(Graphics2D graphics, boolean pixel)
	{
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, smoothText && !pixel
			? RenderingHints.VALUE_TEXT_ANTIALIAS_ON
			: RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}

	void useFont(Graphics2D graphics, int item)
	{
		graphics.setFont(fonts[item]);
		setTextAntialiasing(graphics, pixelFonts[item]);
	}

	void useLevelFont(Graphics2D graphics)
	{
		graphics.setFont(levelFont);
		setTextAntialiasing(graphics, levelItemFont.pixel);
	}

	void applyTextHints(Graphics2D graphics)
	{
		setTextAntialiasing(graphics, pixelFonts[NAME]);
		// Fractional metrics place glyphs between pixels, which makes smoothed text look soft.
		graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
	}

	private static final class ItemFont
	{
		private String family;
		private int size;
		private boolean bold;
		private boolean italic;
		private Font font;
		private boolean pixel;

		boolean update(FontType type, FontType fallback)
		{
			final FontType setting = type != null ? type : fallback;
			final String newFamily = setting.getFamily() != null ? setting.getFamily() : fallback.getFamily();
			final int newSize = clampFontSize(setting.getSize());
			if (font != null && newFamily.equals(family) && newSize == size
				&& setting.isBold() == bold && setting.isItalic() == italic)
			{
				return false;
			}

			family = newFamily;
			size = newSize;
			bold = setting.isBold();
			italic = setting.isItalic();
			pixel = isRunescapeFont(family);
			font = FontManager.getFallbackFont(family, (bold ? Font.BOLD : Font.PLAIN) | (italic ? Font.ITALIC : Font.PLAIN), size);
			return true;
		}
	}
}

package com.ghordrin.bosshealthbar.render;

import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.KnownBosses;
import com.ghordrin.bosshealthbar.theme.BarTheme;
import com.ghordrin.bosshealthbar.theme.HealthBarTheme;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.ImageUtil;

// The icons the bar draws: the one in the crests and the one in front of the name. The boss sprite is kept at the
// size the crest wants, so it is only resized when the boss changes.
@Singleton
public class BarIcons
{
	private final BossHealthBarConfig config;
	private final SpriteManager spriteManager;
	private final ItemManager itemManager;

	private int bossSpriteId = -1;
	private BufferedImage bossSprite;

	@Inject
	private BarIcons(BossHealthBarConfig config, SpriteManager spriteManager, ItemManager itemManager)
	{
		this.config = config;
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
	}

	// Without crests, the boss's icon goes small before the name, as on the Oldschool theme.
	public BufferedImage nameIcon(KnownBosses.Icon icon, boolean showingPreview)
	{
		if (config.showIcons() || !config.useBossIcon() || showingPreview || icon == null)
		{
			return null;
		}
		return bossIcon(icon);
	}

	public BufferedImage crestIcon(BarTheme theme, KnownBosses.Icon icon, boolean showingPreview)
	{
		if (!config.showIcons())
		{
			return null;
		}

		if (config.useBossIcon() && !showingPreview && icon != null)
		{
			final BufferedImage bossIcon = bossIcon(icon);
			if (bossIcon != null)
			{
				return bossIcon;
			}
		}

		if (theme == HealthBarTheme.CUSTOM)
		{
			final int itemId = config.customIconItemId();
			return itemId > 0 ? itemManager.getImage(itemId) : null;
		}

		final Integer godIconSpriteId = theme.getGodIconSpriteId();
		return godIconSpriteId != null ? spriteManager.getSprite(godIconSpriteId, 0) : null;
	}

	private BufferedImage bossIcon(KnownBosses.Icon icon)
	{
		if (icon.isItem())
		{
			return itemManager.getImage(icon.getId());
		}

		if (icon.getId() != bossSpriteId)
		{
			final BufferedImage sprite = spriteManager.getSprite(icon.getId(), 0);
			if (sprite == null)
			{
				return null;
			}
			// The crest draws its icon into a square, so pad the sprite rather than stretch it.
			final int size = Math.max(sprite.getWidth(), sprite.getHeight());
			bossSprite = ImageUtil.resizeCanvas(sprite, size, size);
			bossSpriteId = icon.getId();
		}
		return bossSprite;
	}
}

package com.ghordrin.bosshealthbar.render;

import java.util.Arrays;

// Places the items of one text row around the bar. Item indexes double as importance: a lower index is
// handed space first and sits closer to its spot's edge.
class BarLayout
{
	static final int NOT_PLACED = Integer.MIN_VALUE;

	enum Spot
	{
		LEFT,
		CENTER,
		RIGHT
	}

	private final Spot[] spots;
	private final int[] widths;
	private final boolean[] kept;
	private final int[] xs;

	private int width;
	private int left;
	private int right;
	private int gap;

	private int leftEnd;
	private int rightStart;
	private int centerStart;
	private int centerWidth;
	private boolean leftUsed;
	private boolean rightUsed;
	private boolean centerUsed;

	BarLayout(int size)
	{
		spots = new Spot[size];
		widths = new int[size];
		kept = new boolean[size];
		xs = new int[size];
		clear();
	}

	void clear()
	{
		Arrays.fill(spots, null);
		Arrays.fill(kept, false);
		Arrays.fill(xs, NOT_PLACED);
	}

	void add(int item, Spot spot, int itemWidth)
	{
		spots[item] = spot;
		widths[item] = itemWidth;
	}

	void addKept(int item, Spot spot, int itemWidth)
	{
		add(item, spot, itemWidth);
		kept[item] = true;
	}

	void setWidth(int item, int itemWidth)
	{
		widths[item] = itemWidth;
	}

	Spot spot(int item)
	{
		return spots[item];
	}

	int x(int item)
	{
		return xs[item];
	}

	int width(int item)
	{
		return widths[item];
	}

	void layout(int rowWidth, int leftEdge, int rightEdge, int itemGap)
	{
		width = rowWidth;
		left = leftEdge;
		right = rightEdge;
		gap = itemGap;
		leftUsed = rightUsed = centerUsed = false;
		leftEnd = left;
		rightStart = right;
		centerWidth = 0;
		centerStart = 0;
		boolean leftOpen = true;
		boolean rightOpen = true;
		boolean centerOpen = true;
		Arrays.fill(xs, NOT_PLACED);

		for (int item = 0; item < spots.length; item++)
		{
			final Spot spot = spots[item];
			if (spot == null)
			{
				continue;
			}

			final int itemWidth = widths[item];
			if (spot == Spot.LEFT && leftOpen)
			{
				final int x = leftLimit();
				final int end = x + itemWidth;
				if (kept[item] || end <= rightLimit() && (!centerUsed || end + gap <= centerStart))
				{
					xs[item] = x;
					leftEnd = end;
					leftUsed = true;
				}
				else
				{
					leftOpen = false;
				}
			}
			else if (spot == Spot.RIGHT && rightOpen)
			{
				final int end = rightLimit();
				final int x = end - itemWidth;
				if (kept[item] || x >= leftLimit() && (!centerUsed || x >= centerStart + centerWidth + gap))
				{
					xs[item] = x;
					rightStart = x;
					rightUsed = true;
				}
				else
				{
					rightOpen = false;
				}
			}
			else if (spot == Spot.CENTER && centerOpen)
			{
				final int groupWidth = centerUsed ? centerWidth + gap + itemWidth : itemWidth;
				final int groupStart = Math.floorDiv(width - groupWidth, 2);
				if (kept[item] || groupStart >= leftLimit() && groupStart + groupWidth <= rightLimit())
				{
					// The real x is set below, once the group's final width is known.
					xs[item] = 0;
					centerWidth = groupWidth;
					centerStart = groupStart;
					centerUsed = true;
				}
				else
				{
					centerOpen = false;
				}
			}
		}

		int x = centerStart;
		for (int item = 0; item < spots.length; item++)
		{
			if (spots[item] == Spot.CENTER && xs[item] != NOT_PLACED)
			{
				xs[item] = x;
				x += widths[item] + gap;
			}
		}
	}

	// How much wider a placed item could be without moving into the space of anything else placed on the row.
	int room(int item)
	{
		if (xs[item] == NOT_PLACED)
		{
			return 0;
		}

		final int slack;
		switch (spots[item])
		{
			case LEFT:
				slack = Math.min(rightLimit(), centerUsed ? centerStart - gap : Integer.MAX_VALUE) - leftEnd;
				break;
			case RIGHT:
				slack = rightStart - Math.max(leftLimit(), centerUsed ? centerStart + centerWidth + gap : Integer.MIN_VALUE);
				break;
			default:
				// The group stays centred, so it can only grow as far as the closer side allows, on both sides.
				final int maxWidth = Math.min(width - 2 * leftLimit(), 2 * rightLimit() + 1 - width);
				slack = maxWidth - centerWidth;
				break;
		}
		return Math.max(0, slack);
	}

	// NOT_PLACED when, centred, it would run into a placed item other than ignoredItem.
	int centredX(int itemWidth, int ignoredItem)
	{
		final int x = Math.floorDiv(width - itemWidth, 2);
		final int end = x + itemWidth;
		for (int item = 0; item < spots.length; item++)
		{
			if (item != ignoredItem && xs[item] != NOT_PLACED && x < xs[item] + widths[item] + gap && xs[item] < end + gap)
			{
				return NOT_PLACED;
			}
		}
		return x;
	}

	private int leftLimit()
	{
		return leftUsed ? leftEnd + gap : left;
	}

	private int rightLimit()
	{
		return rightUsed ? rightStart - gap : right;
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.brighten;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.darken;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.lerp;
import static com.ghordrin.bosshealthbar.theme.ColorUtil.withAlpha;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.data.BarState;
import com.ghordrin.bosshealthbar.integrations.HealthIndicatorMarkers;
