package com.ghordrin.bosshealthbar.gamebars;

import static com.ghordrin.bosshealthbar.gamebars.PillarBars.FADE_IN_SCRIPT;
import static com.ghordrin.bosshealthbar.gamebars.PillarBars.FADE_OUT_SCRIPT;
import static com.ghordrin.bosshealthbar.gamebars.PillarBars.UPDATE_SCRIPT;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.debug.DebugLog;
import java.awt.Dimension;
import java.util.List;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

public class PillarBarsTest
{
	private static final int NW = InterfaceID.NightmareTotems.TOTEM_NW_BAR_BACK;
	private static final int NE = InterfaceID.NightmareTotems.TOTEM_NE_BAR_BACK;
	private static final int SW = InterfaceID.NightmareTotems.TOTEM_SW_BAR_BACK;
	private static final int SE = InterfaceID.NightmareTotems.TOTEM_SE_BAR_BACK;
	private static final float DELTA = 0.0001f;

	private final DebugLog debugLog = new DebugLog(null);
	private final PillarBars bars = new PillarBars(null, debugLog);

	private static Object[] update(int[]... groups)
	{
		final Object[] args = new Object[PillarBars.UPDATE_ARGS];
		args[0] = UPDATE_SCRIPT;
		for (int group = 0; group < groups.length; group++)
		{
			for (int i = 0; i < 4; i++)
			{
				args[1 + group * 4 + i] = groups[group][i];
			}
		}
		args[PillarBars.UPDATE_ARGS - 1] = 0;
		return args;
	}

	private static int[] group(int back, int max, int current)
	{
		return new int[]{back, back + 1, max, current};
	}

	@Test
	public void parsesByComponentInAnyOrder()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(SE, 100, 10), group(NW, 100, 40), group(NE, 100, 70), group(SW, 50, 25)));

		assertEquals(0.4f, bars.fraction(0), DELTA);
		assertEquals(0.7f, bars.fraction(1), DELTA);
		assertEquals(0.5f, bars.fraction(2), DELTA);
		assertEquals(0.1f, bars.fraction(3), DELTA);
	}

	@Test
	public void unchangedValueKeepsTheBar()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 40), group(SW, 100, 40), group(SE, 100, 40)));
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, -1), group(NE, -1, 50), group(SW, 0, 80), group(SE, 100, 60)));

		assertEquals(0.4f, bars.fraction(0), DELTA);
		assertEquals(0.5f, bars.fraction(1), DELTA);
		assertEquals(0.4f, bars.fraction(2), DELTA);
		assertEquals(0.6f, bars.fraction(3), DELTA);
	}

	@Test
	public void onlyChangedValuesAreLogged()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 40), group(SW, 100, 40), group(SE, 100, 40)));
		assertEquals(4, debugLog.snapshot().size());

		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, -1, -1), group(SW, 100, -1), group(SE, -1, 40)));
		assertEquals(4, debugLog.snapshot().size());

		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 41), group(NE, -1, -1), group(SW, 200, -1), group(SE, -1, -1)));
		assertEquals(5, debugLog.snapshot().size());
		assertEquals("Pillar bar 2: 40/200", debugLog.snapshot().get(4).message);

		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 100), group(NE, -1, -1), group(SW, -1, -1), group(SE, -1, -1)));
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 0), group(NE, -1, -1), group(SW, -1, -1), group(SE, -1, -1)));
		final List<DebugLog.Entry> entries = debugLog.snapshot();
		assertEquals(7, entries.size());
		assertEquals("Pillar bar 0: 100/100", entries.get(5).message);
		assertEquals("Pillar bar 0: 0/100", entries.get(6).message);
	}

	@Test
	public void fadesAreLoggedOnlyWhenShownChanges()
	{
		bars.onScript(FADE_OUT_SCRIPT, null);
		assertTrue(debugLog.snapshot().isEmpty());
		bars.onScript(FADE_IN_SCRIPT, null);
		bars.onScript(FADE_IN_SCRIPT, null);
		assertEquals(1, debugLog.snapshot().size());
		assertEquals(1, debugLog.snapshot().get(0).repeats);
	}

	@Test
	public void anUnchangedCurrentIsRescaledByANewMax()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 100), group(SW, 100, 40), group(SE, 100, 40)));
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 200, -1), group(NE, 200, -1), group(SW, -1, -1), group(SE, 50, -1)));

		assertEquals(0.2f, bars.fraction(0), DELTA);
		assertEquals(0.5f, bars.fraction(1), DELTA);
		assertFalse(bars.isFull(1));
		assertEquals(0.4f, bars.fraction(2), DELTA);
		assertEquals(0.8f, bars.fraction(3), DELTA);
	}

	@Test
	public void anUnchangedValueWithNothingStoredIsSkipped()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, 50), group(NE, 100, -1), group(SW, -1, -1), group(SE, 0, 50)));
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
		}

		// The max from the first update is kept for a later current.
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, -1), group(NE, -1, 25), group(SW, -1, -1), group(SE, -1, -1)));
		assertEquals(0.25f, bars.fraction(1), DELTA);
		assertEquals(0f, bars.fraction(0), DELTA);
	}

	@Test
	public void resetForgetsTheStoredValues()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 40), group(NE, 100, 40), group(SW, 100, 40), group(SE, 100, 40)));
		bars.reset();
		bars.onScript(UPDATE_SCRIPT, update(group(NW, -1, 50), group(NE, 200, -1), group(SW, -1, -1), group(SE, -1, -1)));
		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
		}
	}

	@Test
	public void clampsAndSetsFull()
	{
		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 150), group(NE, 100, 100), group(SW, 100, 99), group(SE, 100, 0)));

		assertEquals(1f, bars.fraction(0), DELTA);
		assertTrue(bars.isFull(0));
		assertTrue(bars.isFull(1));
		assertFalse(bars.isFull(2));
		assertFalse(bars.isFull(3));
		assertEquals(0f, bars.fraction(3), DELTA);

		bars.onScript(UPDATE_SCRIPT, update(group(NW, 100, 0), group(NE, 100, 100), group(SW, 100, 99), group(SE, 100, 0)));
		assertFalse(bars.isFull(0));
		assertEquals(0f, bars.fraction(0), DELTA);
	}

	@Test
	public void fadeScriptsShowAndHide()
	{
		assertFalse(bars.isShown());
		bars.onScript(FADE_IN_SCRIPT, new Object[]{FADE_IN_SCRIPT});
		assertTrue(bars.isShown());
		bars.onScript(FADE_OUT_SCRIPT, null);
		assertFalse(bars.isShown());
	}

	@Test
	public void ignoresOtherScriptsAndBadArguments()
	{
		bars.onScript(UPDATE_SCRIPT + 1, update(group(NW, 100, 50), group(NE, 100, 50), group(SW, 100, 50), group(SE, 100, 50)));
		bars.onScript(UPDATE_SCRIPT, null);
		bars.onScript(UPDATE_SCRIPT, new Object[]{UPDATE_SCRIPT, NW, NW + 1, 100, 50});

		final Object[] wrongTypes = update(group(NW, 100, 50), group(NE, 100, 50), group(SW, 100, 50), group(SE, 100, 50));
		wrongTypes[1] = "text";
		wrongTypes[8] = null;
		wrongTypes[12] = "text";
		wrongTypes[13] = 12345;
		bars.onScript(UPDATE_SCRIPT, wrongTypes);

		for (int corner = 0; corner < PillarBars.CORNERS; corner++)
		{
			assertEquals(0f, bars.fraction(corner), DELTA);
			assertFalse(bars.isFull(corner));
		}
		assertFalse(bars.isShown());
		assertFalse(bars.isVisible());
	}

	@Test
	public void mapsCorners()
	{
		assertEquals(0, PillarBars.corner(NW));
		assertEquals(1, PillarBars.corner(NE));
		assertEquals(2, PillarBars.corner(SW));
		assertEquals(3, PillarBars.corner(SE));
		assertEquals(-1, PillarBars.corner(-1));
	}

	@Test
	public void seedsFromWidths()
	{
		assertEquals(0.5f, PillarBars.seedFraction(30, 60), DELTA);
		assertEquals(1f, PillarBars.seedFraction(60, 60), DELTA);
		assertEquals(0f, PillarBars.seedFraction(30, 0), DELTA);
		assertEquals(0f, PillarBars.seedFraction(0, -1), DELTA);
		assertTrue(PillarBars.seedFull(60, 60));
		assertFalse(PillarBars.seedFull(59, 60));
		assertFalse(PillarBars.seedFull(0, 0));
	}

	@Test
	public void layoutSize()
	{
		assertEquals(64, PillarBarsOverlay.barWidth(40));
		assertEquals(74, PillarBarsOverlay.barWidth(70));
		assertEquals(5, PillarBarsOverlay.barHeight(4));
		assertEquals(9, PillarBarsOverlay.barHeight(24));
		assertEquals(7, PillarBarsOverlay.barHeight(7));
		assertEquals(22, PillarBarsOverlay.cellHeight(12, 9));
		assertEquals(new Dimension(134, 47), PillarBarsOverlay.gridSize(64, 22));
	}

	@Test
	public void filledWidth()
	{
		assertEquals(62, PillarBarsOverlay.filledWidth(62, 0.2f, true));
		assertEquals(31, PillarBarsOverlay.filledWidth(62, 0.5f, false));
		assertEquals(0, PillarBarsOverlay.filledWidth(62, 0f, false));
		assertEquals(62, PillarBarsOverlay.filledWidth(62, 1.5f, false));
	}
}

package com.ghordrin.bosshealthbar.integrations;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import java.awt.Color;
import org.junit.Test;

public class HealthIndicatorMarkersTest
{
	private static final Gson GSON = new Gson();

	// java.awt.Color written field by field, as Gson does without a color type adapter.
	private static final String SAVED = "[{\"bossName\":\"Big Boss\",\"entries\":["
		+ "{\"percentage\":0.5,\"color\":{\"value\":-65536,\"falpha\":0.0},\"notify\":true},"
		+ "{\"percentage\":0.25,\"color\":{\"value\":-16711936,\"falpha\":0.0},\"notify\":false}]},"
		+ "{\"bossName\":\"Big.*\",\"entries\":[{\"percentage\":0.75,\"color\":{\"value\":-16776961},\"notify\":false}]}]";

	@Test
	public void readsMarkersForMatchingBosses()
	{
		final HealthIndicatorMarkers.Marker[] markers = HealthIndicatorMarkers.markersFor(GSON, SAVED, "Big Boss");

		assertEquals(3, markers.length);
		assertEquals(new HealthIndicatorMarkers.Marker(0.5f, Color.RED), markers[0]);
		assertEquals(new HealthIndicatorMarkers.Marker(0.25f, Color.GREEN), markers[1]);
		assertEquals(new HealthIndicatorMarkers.Marker(0.75f, Color.BLUE), markers[2]);
	}

	@Test
	public void readsHexColorsAsSavedThroughRuneLitesGson()
	{
		final String saved = "[{\"bossName\":\"Zulrah\",\"entries\":["
			+ "{\"percentage\":0.7,\"color\":\"#FFF53B3B\",\"notify\":true},"
			+ "{\"percentage\":0.3,\"color\":\"#FFFFFFFF\",\"notify\":true}]},"
			+ "{\"bossName\":\"Yama\",\"entries\":[]}]";

		final HealthIndicatorMarkers.Marker[] markers = HealthIndicatorMarkers.markersFor(GSON, saved, "Zulrah");
		assertEquals(2, markers.length);
		assertEquals(new HealthIndicatorMarkers.Marker(0.7f, new Color(0xF53B3B)), markers[0]);
		assertEquals(new HealthIndicatorMarkers.Marker(0.3f, Color.WHITE), markers[1]);

		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON, saved, "Yama").length);
	}

	@Test
	public void namesAreMatchedAsAWholeRegex()
	{
		assertEquals(1, HealthIndicatorMarkers.markersFor(GSON, SAVED, "Bigger Boss").length);
		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON, SAVED, "A Big Boss").length);
	}

	@Test
	public void skipsAnythingUnexpected()
	{
		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON, null, "Big Boss").length);
		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON, "not json {", "Big Boss").length);
		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON, "{\"bossName\":\"Big Boss\"}", "Big Boss").length);
		assertEquals(0, HealthIndicatorMarkers.markersFor(GSON,
			"[{\"bossName\":\"[\",\"entries\":[{\"percentage\":0.5,\"color\":{\"value\":-1}}]}]", "[").length);

		final String mixed = "[{\"bossName\":\"Big Boss\",\"entries\":["
			+ "{\"percentage\":1.5,\"color\":{\"value\":-1}},"
			+ "{\"percentage\":0.5},"
			+ "{\"percentage\":\"half\",\"color\":{\"value\":-1}},"
			+ "{\"percentage\":0.4,\"color\":{\"value\":-1}}]}]";
		assertEquals(1, HealthIndicatorMarkers.markersFor(GSON, mixed, "Big Boss").length);
	}
}

package com.ghordrin.bosshealthbar.integrations;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.ghordrin.bosshealthbar.data.KnownBosses;
import org.junit.Test;

public class KillCountsTest
{
	private static String key(String name)
	{
		final KnownBosses.Boss boss = KnownBosses.find(name);
		return boss != null ? boss.getKillCountKey() : null;
	}

	@Test
	public void usesTheLowercasedName()
	{
		assertEquals("zulrah", key("Zulrah"));
		assertEquals("k'ril tsutsaroth", key("K'ril Tsutsaroth"));
		assertEquals("dagannoth rex", key("Dagannoth Rex"));
	}

	@Test
	public void stripsColorTags()
	{
		assertEquals("vorkath", key("<col=ffff00>Vorkath</col>"));
		assertEquals("grotesque guardians", key("<col=00ffff>Dusk</col>"));
	}

	@Test
	public void formsOfOneBossShareAKey()
	{
		assertEquals("grotesque guardians", key("Dawn"));
		assertEquals("barrows chests", key("Dharok the Wretched"));
		assertEquals("lunar chest", key("Eclipse Moon"));
		assertEquals("royal titans", key("Eldric the Ice King"));
		assertEquals("doom of mokhaiotl", key("Doom of Mokhaiotl"));
		assertEquals("doom of mokhaiotl", key("Doom of Mokhaiotl (Burrowed)"));
		assertEquals("yama", key("Judge of Yama"));
	}

	@Test
	public void renamedBossesUseTheirKillCountName()
	{
		assertEquals("gauntlet", key("Crystalline Hunllef"));
		assertEquals("corrupted gauntlet", key("Corrupted Hunllef"));
		assertEquals("nightmare", key("The Nightmare"));
		assertEquals("phosani's nightmare", key("Phosani's Nightmare"));
		assertEquals("leviathan", key("The Leviathan"));
		assertEquals("whisperer", key("The Whisperer"));
		assertEquals("hueycoatl", key("The Hueycoatl"));
	}

	@Test
	public void emptyNamesHaveNoKey()
	{
		assertNull(key(null));
		assertNull(key(""));
		assertNull(key("<col=ff0000></col>"));
	}

	@Test
	public void otherOpponentsHaveNoKey()
	{
		assertNull(key("Mithril dragon"));
		assertNull(key("Wintertodt"));
	}

	@Test
	public void everyFormSharingACountUsesItsName()
	{
		assertEquals("grotesque guardians", key("Dusk"));
		assertEquals("barrows chests", key("Ahrim the Blighted"));
		assertEquals("barrows chests", key("Guthan the Infested"));
		assertEquals("barrows chests", key("Karil the Tainted"));
		assertEquals("barrows chests", key("Torag the Corrupted"));
		assertEquals("barrows chests", key("Verac the Defiled"));
		assertEquals("lunar chest", key("Blood Moon"));
		assertEquals("lunar chest", key("Blue Moon"));
		assertEquals("royal titans", key("Branda the Fire Queen"));
		assertEquals("mimic", key("The Mimic"));
		assertEquals("yama", key("Yama"));
		assertEquals("doom of mokhaiotl", key("Doom of Mokhaiotl (Shielded)"));
	}

	@Test
	public void trimsTheName()
	{
		assertEquals("zulrah", key(" Zulrah "));
		assertEquals("grotesque guardians", key("<col=00ffff> Dawn</col>"));
	}

	@Test
	public void formatsTheCount()
	{
		assertEquals("KC 7", KillCounts.text(7));
		assertEquals("KC 1,234", KillCounts.text(1234));
	}

	@Test
	public void missingOrZeroCountsShowNothing()
	{
		assertNull(KillCounts.text(null));
		assertNull(KillCounts.text(0));
	}
}

package com.ghordrin.bosshealthbar.integrations;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import org.junit.Test;

public class PartyDefenceTest
{
	private static class DefenceTrackerPlugin extends Plugin
	{
	}

	private static class OtherPlugin extends Plugin
	{
	}

	private static class DefenceInfoBox extends InfoBox
	{
		private final String text;
		private final Color color;

		DefenceInfoBox(Plugin plugin, String tooltip, String text, Color color)
		{
			this(plugin, null, tooltip, text, color);
		}

		DefenceInfoBox(Plugin plugin, BufferedImage image, String tooltip, String text, Color color)
		{
			super(image, plugin);
			setTooltip(tooltip);
			this.text = text;
			this.color = color;
		}

		@Override
		public String getText()
		{
			return text;
		}

		@Override
		public Color getTextColor()
		{
			return color;
		}
	}

	private static class VulnerabilityInfoBox extends DefenceInfoBox
	{
		VulnerabilityInfoBox(Plugin plugin, String tooltip)
		{
			super(plugin, tooltip, "V", Color.WHITE);
		}
	}

	private static class BetterPartyDefencePlugin extends Plugin
	{
	}

	private static final Plugin TRACKER = new DefenceTrackerPlugin();
	private static final Plugin BETTER = new BetterPartyDefencePlugin();
	private static final BufferedImage DEFENCE_IMAGE = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final BufferedImage MAGIC_IMAGE = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final Predicate<BufferedImage> IS_MAGIC = image -> image == MAGIC_IMAGE;
	private static final Predicate<BufferedImage> NOTHING_IS_MAGIC = image -> false;

	private static DefenceInfoBox box(String tooltip, String text, Color color)
	{
		return new DefenceInfoBox(TRACKER, tooltip, text, color);
	}

	private static DefenceInfoBox betterBox(BufferedImage image, String text, Color color)
	{
		return new DefenceInfoBox(BETTER, image, "No specs yet", text, color);
	}

	@Test
	public void boxesAreNamedLikeTheirs()
	{
		assertEquals(PartyDefence.BOX_NAME, box("Big Boss", "10", Color.WHITE).getName());
		assertEquals(PartyDefence.BETTER_BOX_NAME, betterBox(DEFENCE_IMAGE, "10", Color.WHITE).getName());
	}

	@Test
	public void betterSkipsTheMagicDefenceBox()
	{
		final PartyDefence.Reading reading = PartyDefence.findBetter(Arrays.asList(
			betterBox(MAGIC_IMAGE, "150", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN)), IS_MAGIC);

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), reading);
	}

	@Test
	public void betterTakesTheFirstBoxWhenNeitherIsMagic()
	{
		final PartyDefence.Reading reading = PartyDefence.findBetter(Arrays.asList(
			box("Big Boss", "5", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), "150", Color.WHITE)), IS_MAGIC);

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), reading);
		assertEquals(reading, PartyDefence.findBetter(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "150", Color.WHITE)), NOTHING_IS_MAGIC));
	}

	@Test
	public void betterIgnoresEmptyText()
	{
		assertNull(PartyDefence.findBetter(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "", Color.WHITE),
			betterBox(MAGIC_IMAGE, "150", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.singletonList(betterBox(DEFENCE_IMAGE, null, Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.singletonList(betterBox(MAGIC_IMAGE, "150", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetter(Collections.emptyList(), IS_MAGIC));
	}

	@Test
	public void magicIsTheBoxWithTheMagicImage()
	{
		final List<InfoBox> boxes = Arrays.asList(
			box("Big Boss", "5", Color.WHITE),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "150", Color.YELLOW));

		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(boxes, IS_MAGIC));
		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(MAGIC_IMAGE, "150", Color.YELLOW),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN)), IS_MAGIC));
	}

	@Test
	public void unrecognisedImagesGiveDefenceFromTheFirstBoxAndNoMagic()
	{
		final List<InfoBox> boxes = Arrays.asList(
			betterBox(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), "150", Color.YELLOW),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetter(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(boxes, IS_MAGIC));
	}

	@Test
	public void themedMagicIconIsFoundByItsPixelsInEitherOrder()
	{
		final BufferedImage skillMagic = icon(25, 0xFF2040C0);
		final BufferedImage skillDefence = icon(25, 0xFFA0A0A0);
		final MagicIconMatcher matcher = new MagicIconMatcher();
		final Predicate<BufferedImage> isMagic = image -> matcher.isMagic(image, skillMagic, null);
		final InfoBox themedMagic = betterBox(MagicIconMatcher.themed(skillMagic), "150", Color.YELLOW);
		final InfoBox themedDefence = betterBox(MagicIconMatcher.themed(skillDefence), "120", Color.GREEN);

		for (List<InfoBox> boxes : Arrays.asList(Arrays.asList(themedMagic, themedDefence),
			Arrays.asList(themedDefence, themedMagic)))
		{
			assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.findBetter(boxes, isMagic));
			assertEquals(new PartyDefence.Reading("150", Color.YELLOW), PartyDefence.findBetterMagic(boxes, isMagic));
		}
	}

	@Test
	public void themedMagicIconFromAnOverrideIsFoundByItsPixels()
	{
		final BufferedImage skillMagic = icon(25, 0xFF2040C0);
		final BufferedImage override = icon(30, 0xFF10E020);
		final MagicIconMatcher matcher = new MagicIconMatcher();

		assertTrue(matcher.isMagic(MagicIconMatcher.themed(override), skillMagic, override));
		assertTrue(matcher.isMagic(MagicIconMatcher.themed(skillMagic), skillMagic, override));
		assertTrue(matcher.isMagic(skillMagic, skillMagic, null));
		assertFalse(matcher.isMagic(MagicIconMatcher.themed(override), skillMagic, null));
		assertFalse(matcher.isMagic(MagicIconMatcher.themed(icon(25, 0xFFA0A0A0)), skillMagic, override));
		assertFalse(matcher.isMagic(null, skillMagic, override));
	}

	private static BufferedImage icon(int size, int argb)
	{
		final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		for (int y = 2; y < size - 2; y++)
		{
			for (int x = y % 3; x < size - 2; x += 2)
			{
				image.setRGB(x, y, argb);
			}
		}
		return image;
	}

	@Test
	public void aSingleBoxWithoutTheMagicImageIsDefence()
	{
		final List<InfoBox> boxes = Collections.singletonList(betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.findBetter(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(boxes, IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(Collections.singletonList(box("Big Boss", "24", Color.RED)), IS_MAGIC));
	}

	@Test
	public void magicIgnoresEmptyText()
	{
		assertNull(PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, "", Color.WHITE)), IS_MAGIC));
		assertNull(PartyDefence.findBetterMagic(Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			betterBox(MAGIC_IMAGE, null, Color.WHITE)), IS_MAGIC));
	}

	@Test
	public void betterIsUsedWhenItsOn()
	{
		final List<InfoBox> boxes = Arrays.asList(
			box("Big Boss", "24", Color.RED),
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN));

		assertEquals(new PartyDefence.Reading("120", Color.GREEN), PartyDefence.select(boxes, "Big Boss", true, IS_MAGIC));
		assertNull(PartyDefence.select(Collections.singletonList(box("Big Boss", "24", Color.RED)), "Big Boss", true, IS_MAGIC));
	}

	@Test
	public void trackerIsUsedWhenBetterIsOff()
	{
		final List<InfoBox> boxes = Arrays.asList(
			betterBox(DEFENCE_IMAGE, "120", Color.GREEN),
			box("Small Boss", "5", Color.WHITE),
			box("Big Boss", "24", Color.RED));

		assertEquals(new PartyDefence.Reading("24", Color.RED), PartyDefence.select(boxes, "Big Boss", false, NOTHING_IS_MAGIC));
		assertNull(PartyDefence.select(boxes, "Other Boss", false, NOTHING_IS_MAGIC));
	}

	@Test
	public void matchesTheTooltipWithoutColorTagsOrCase()
	{
		assertTrue(PartyDefence.matches(box("<col=ffffff>Big Boss</col>", "10", Color.WHITE), "Big Boss"));
		assertTrue(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "big boss"));
		assertTrue(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "<col=ffff00>Big Boss</col>"));
		assertFalse(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), "Bigger Boss"));
	}

	@Test
	public void ignoresOtherBoxesAndMissingValues()
	{
		assertFalse(PartyDefence.matches(new VulnerabilityInfoBox(TRACKER, "Big Boss"), "Big Boss"));
		assertFalse(PartyDefence.matches(new DefenceInfoBox(new OtherPlugin(), "Big Boss", "10", Color.WHITE), "Big Boss"));
		assertFalse(PartyDefence.matches(box(null, "10", Color.WHITE), "Big Boss"));
		assertFalse(PartyDefence.matches(box("Big Boss", "10", Color.WHITE), null));
		assertFalse(PartyDefence.matches(null, "Big Boss"));
	}

	@Test
	public void picksTheBoxForTheOpponent()
	{
		final PartyDefence.Reading reading = PartyDefence.find(Arrays.asList(
			new VulnerabilityInfoBox(TRACKER, "Big Boss"),
			box("Small Boss", "5", Color.WHITE),
			box("", "7", Color.WHITE),
			box("<col=ffffff>Big Boss</col>", "", Color.WHITE),
			box("<col=ffffff>Big Boss</col>", "24", Color.RED)), "Big Boss");

		assertEquals(new PartyDefence.Reading("24", Color.RED), reading);
	}

	@Test
	public void findsNothingWithoutAMatch()
	{
		assertNull(PartyDefence.find(Collections.emptyList(), "Big Boss"));
		assertNull(PartyDefence.find(Collections.singletonList(box("Small Boss", "5", Color.WHITE)), "Big Boss"));
		assertNull(PartyDefence.find(Collections.singletonList(box("Big Boss", null, Color.WHITE)), "Big Boss"));
	}
}

package com.ghordrin.bosshealthbar.integrations;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import java.awt.Color;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class PluginReaderTest
{
	@Test
	public void keepsTheReadingForOneTickWhenTheBoxIsMissing()
	{
		final PluginReader.HeldReading<PartyDefence.Reading> defence = new PluginReader.HeldReading<>();
		final PartyDefence.Reading reading = new PartyDefence.Reading("24", Color.RED);

		defence.accept("Big Boss", reading);
		assertSame(reading, defence.readingFor("Big Boss"));

		defence.accept("Big Boss", null);
		assertSame(reading, defence.readingFor("Big Boss"));

		defence.accept("Big Boss", null);
		assertNull(defence.readingFor("Big Boss"));
	}

	@Test
	public void aNewReadingResetsTheMissedTick()
	{
		final PluginReader.HeldReading<PartyDefence.Reading> defence = new PluginReader.HeldReading<>();
		final PartyDefence.Reading first = new PartyDefence.Reading("24", Color.RED);
		final PartyDefence.Reading second = new PartyDefence.Reading("20", Color.RED);

		defence.accept("Big Boss", first);
		defence.accept("Big Boss", null);
		defence.accept("Big Boss", second);
		defence.accept("Big Boss", null);
		assertSame(second, defence.readingFor("Big Boss"));
	}

	@Test
	public void readingIsOnlyForTheSameName()
	{
		final PluginReader.HeldReading<PartyDefence.Reading> defence = new PluginReader.HeldReading<>();
		defence.accept("Big Boss", new PartyDefence.Reading("24", Color.RED));

		assertNull(defence.readingFor("Small Boss"));
		assertNull(defence.readingFor(null));

		defence.accept("Small Boss", null);
		assertNull(defence.readingFor("Big Boss"));
		assertNull(defence.readingFor("Small Boss"));
	}

	@Test
	public void keepsAListReadingForOneTick()
	{
		final PluginReader.HeldReading<List<String>> counts = new PluginReader.HeldReading<>();
		final List<String> found = Arrays.asList("2");

		counts.accept(null, found);
		assertSame(found, counts.reading());

		counts.accept(null, null);
		assertSame(found, counts.reading());

		counts.accept(null, null);
		assertNull(counts.reading());
	}

	@Test
	public void aNewListResetsTheMissedTick()
	{
		final PluginReader.HeldReading<List<String>> counts = new PluginReader.HeldReading<>();
		final List<String> first = Arrays.asList("2");
		final List<String> second = Arrays.asList("3");

		counts.accept(null, first);
		counts.accept(null, null);
		counts.accept(null, second);
		counts.accept(null, null);
		assertSame(second, counts.reading());
	}

	@Test
	public void unchangedReadingsKeepTheSameList()
	{
		final PluginReader.HeldReading<List<String>> counts = new PluginReader.HeldReading<>();
		final List<String> first = Arrays.asList("2");

		counts.accept(null, first);
		counts.accept(null, Arrays.asList("2"));
		assertSame(first, counts.reading());
	}
}

package com.ghordrin.bosshealthbar.integrations;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.render.BarTextPainter;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import org.junit.Test;

public class SpecialAttackCountsTest
{
	private static class SpecialCounterPlugin extends Plugin
	{
	}

	private static class OtherPlugin extends Plugin
	{
	}

	private static class SpecialCounter extends InfoBox
	{
		private final String text;
		private final Color color;

		SpecialCounter(Plugin plugin, BufferedImage image, String text, Color color)
		{
			super(image, plugin);
			this.text = text;
			this.color = color;
		}

		@Override
		public String getText()
		{
			return text;
		}

		@Override
		public Color getTextColor()
		{
			return color;
		}
	}

	private static class OtherCounter extends SpecialCounter
	{
		OtherCounter(Plugin plugin)
		{
			super(plugin, null, "1", Color.WHITE);
		}
	}

	private static final Plugin COUNTER_PLUGIN = new SpecialCounterPlugin();
	private static final BufferedImage MAUL = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	private static final BufferedImage GODSWORD = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

	private static SpecialCounter box(BufferedImage image, String text, Color color)
	{
		return new SpecialCounter(COUNTER_PLUGIN, image, text, color);
	}

	private static List<SpecialAttackCounts.Reading> readings(SpecialAttackCounts.Reading... readings)
	{
		return Arrays.asList(readings);
	}

	@Test
	public void boxesAreNamedLikeTheirs()
	{
		assertEquals(SpecialAttackCounts.BOX_NAME, box(MAUL, "2", Color.WHITE).getName());
	}

	@Test
	public void ignoresOtherBoxes()
	{
		assertTrue(SpecialAttackCounts.matches(box(MAUL, "2", Color.WHITE)));
		assertFalse(SpecialAttackCounts.matches(new OtherCounter(COUNTER_PLUGIN)));
		assertFalse(SpecialAttackCounts.matches(new SpecialCounter(new OtherPlugin(), MAUL, "2", Color.WHITE)));
		assertFalse(SpecialAttackCounts.matches(null));
	}

	@Test
	public void findsEveryCountInInfoBoxOrder()
	{
		final List<SpecialAttackCounts.Reading> found = SpecialAttackCounts.find(Arrays.asList(
			box(MAUL, "2", Color.WHITE),
			new OtherCounter(COUNTER_PLUGIN),
			box(null, "", Color.WHITE),
			box(null, null, Color.WHITE),
			box(GODSWORD, "31", Color.GREEN)));

		assertEquals(readings(
			new SpecialAttackCounts.Reading(MAUL, "2", Color.WHITE),
			new SpecialAttackCounts.Reading(GODSWORD, "31", Color.GREEN)), found);
	}

	@Test
	public void findsNothingWithoutBoxes()
	{
		assertTrue(SpecialAttackCounts.find(Collections.emptyList()).isEmpty());
		assertTrue(SpecialAttackCounts.find(Collections.singletonList(new OtherCounter(COUNTER_PLUGIN))).isEmpty());
	}

	@Test
	public void groupWidthCoversEveryWeapon()
	{
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		final FontMetrics metrics = graphics.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		graphics.dispose();

		final List<SpecialAttackCounts.Reading> noIcons = readings(
			new SpecialAttackCounts.Reading(null, "2", Color.WHITE),
			new SpecialAttackCounts.Reading(null, "31", Color.WHITE));
		assertEquals(10 + metrics.stringWidth("2") + 6 + metrics.stringWidth("31"),
			BarTextPainter.specialAttacksEnd(noIcons, metrics, 10, 13));

		// A 36x32 item image at height 13 is 15 wide with 1px of padding each side, plus the 3px gap.
		final BufferedImage itemImage = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		final List<SpecialAttackCounts.Reading> withIcon = readings(new SpecialAttackCounts.Reading(itemImage, "2", Color.WHITE));
		assertEquals(10 + 16 + metrics.stringWidth("2"), BarTextPainter.specialAttacksEnd(withIcon, metrics, 10, 13));
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarAnimation.clamp01;
import static com.ghordrin.bosshealthbar.render.BarAnimation.easeOut;
import static com.ghordrin.bosshealthbar.render.BarAnimation.progress;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.time.Duration;
import org.junit.Test;

public class BarAnimationTest
{
	@Test
	public void lostHealthLeavesATrail()
	{
		final BarAnimation animation = new BarAnimation();
		animation.tick(1f, 1f, true, System.currentTimeMillis());
		animation.tick(0.4f, 1f, true, System.currentTimeMillis());

		assertEquals(0.4f, animation.getDisplayedFraction(), 0.001f);
		assertTrue(animation.getTrailFraction() > 0.9f);
	}

	@Test
	public void retargetJumpsToTheNewHealthWithoutATrail()
	{
		final BarAnimation animation = new BarAnimation();
		animation.tick(0.4f, 1f, true, System.currentTimeMillis());
		animation.retarget();
		animation.tick(1f, 1f, true, System.currentTimeMillis());

		assertEquals(1f, animation.getDisplayedFraction(), 0.001f);
		assertEquals(1f, animation.getTrailFraction(), 0.001f);

		animation.retarget();
		animation.tick(0.2f, 1f, true, System.currentTimeMillis());

		assertEquals(0.2f, animation.getDisplayedFraction(), 0.001f);
		assertEquals(0.2f, animation.getTrailFraction(), 0.001f);
	}

	@Test
	public void defeatEndsAfterTheFadeOrTheBurn()
	{
		final long hold = BarAnimation.DEFEAT_HOLD.toNanos();
		for (boolean burnAway : new boolean[]{false, true})
		{
			final BarAnimation animation = new BarAnimation();
			animation.startDefeat(1_000L);
			final long end = 1_000L + hold + (burnAway ? BarEffects.BURN_DURATION : BarAnimation.DEFEAT_FADE).toNanos();
			assertEquals(1f, animation.defeatOpacity(1_000L + hold, burnAway), 0.001f);
			assertTrue(animation.defeatOpacity(end - 1_000_000L, burnAway) >= 0f);
			assertEquals(-1f, animation.defeatOpacity(end, burnAway), 0f);
		}
	}

	@Test
	public void aHeldDefeatStaysOnDefeatedAndFadesOnceLetGo()
	{
		final long hold = BarAnimation.DEFEAT_HOLD.toNanos();
		final long fade = BarAnimation.DEFEAT_FADE.toNanos();
		final BarAnimation animation = new BarAnimation();
		animation.startDefeat(1_000L);
		final long later = 1_000L + hold + fade * 3;
		animation.holdDefeat(later, fade * 10);
		assertEquals(1f, animation.defeatOpacity(later, false), 0f);
		assertEquals(0, animation.defeatEffectMillis(later));
		assertEquals(-1f, animation.defeatOpacity(later + fade, false), 0f);
	}

	@Test
	public void aDefeatIsOnlyHeldUpToTheLimit()
	{
		final long hold = BarAnimation.DEFEAT_HOLD.toNanos();
		final long limit = hold * 3;
		final BarAnimation animation = new BarAnimation();
		animation.startDefeat(1_000L);
		animation.holdDefeat(1_000L + limit - 1, limit);
		assertEquals(0, animation.defeatEffectMillis(1_000L + limit - 1));
		// Past the limit it fades even while still held.
		final long past = 1_000L + limit + hold;
		animation.holdDefeat(past, limit);
		assertTrue(animation.defeatEffectMillis(past) > 0);
		// A limit below the normal hold still holds that long.
		final BarAnimation shortLimit = new BarAnimation();
		shortLimit.startDefeat(1_000L);
		shortLimit.holdDefeat(1_000L + hold - 1, 0);
		assertEquals(1f, shortLimit.defeatOpacity(1_000L + hold - 1, false), 0f);
	}

	@Test
	public void burnAwayFadesOnlyTheText()
	{
		final BarAnimation animation = new BarAnimation();
		animation.startDefeat(1_000L);
		final long halfway = 1_000L + BarAnimation.DEFEAT_HOLD.toNanos() + BarAnimation.DEFEAT_FADE.toNanos() / 2;

		assertEquals(0.5f, animation.defeatOpacity(halfway, false), 0.01f);
		assertEquals(1f, animation.defeatTextOpacity(halfway, false), 0f);
		assertEquals(1f, animation.defeatOpacity(halfway, true), 0f);
		assertEquals(0.5f, animation.defeatTextOpacity(halfway, true), 0.01f);
		assertEquals(BarAnimation.DEFEAT_FADE.toMillis() / 2, animation.defeatEffectMillis(halfway));
	}

	@Test
	public void noDefeatMeansNoDefeatEffect()
	{
		final BarAnimation animation = new BarAnimation();
		assertEquals(1f, animation.defeatOpacity(5_000_000_000L, true), 0f);
		assertEquals(1f, animation.defeatTextOpacity(5_000_000_000L, true), 0f);
		assertTrue(animation.defeatEffectMillis(5_000_000_000L) < 0);
	}

	@Test
	public void clampKeepsFractionsInRange()
	{
		assertEquals(0f, clamp01(-5f), 0f);
		assertEquals(1f, clamp01(5f), 0f);
		assertEquals(0.25f, clamp01(0.25f), 0f);
	}

	@Test
	public void progressRunsFromZeroToOneAcrossTheDuration()
	{
		final Duration delay = Duration.ofMillis(100);
		final Duration duration = Duration.ofMillis(400);

		assertEquals(0f, progress(Duration.ofMillis(50).toNanos(), delay, duration), 0.0001f);
		assertEquals(0f, progress(delay.toNanos(), delay, duration), 0.0001f);
		assertEquals(0.5f, progress(Duration.ofMillis(300).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Duration.ofMillis(500).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Duration.ofSeconds(10).toNanos(), delay, duration), 0.0001f);
		assertEquals(1f, progress(Long.MAX_VALUE, delay, duration), 0.0001f);
	}

	@Test
	public void easeOutKeepsItsEndsAndOnlyMovesForward()
	{
		assertEquals(0f, easeOut(0f), 0.0001f);
		assertEquals(1f, easeOut(1f), 0.0001f);

		float previous = -1f;
		for (int i = 0; i <= 100; i++)
		{
			final float eased = easeOut(i / 100f);
			assertTrue("eased value went backwards at " + i, eased > previous);
			assertTrue("eased value left the range at " + i, eased >= 0f && eased <= 1f);
			previous = eased;
		}

		assertTrue(easeOut(0.5f) > 0.5f);
	}
}

package com.ghordrin.bosshealthbar.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BarEffectsTest
{
	@Test
	public void randomIsRepeatableAndInRange()
	{
		for (int i = 0; i < 1000; i++)
		{
			final float value = BarEffects.random(42, i);
			assertTrue(value >= 0f && value < 1f);
			assertEquals(value, BarEffects.random(42, i), 0f);
		}
		assertTrue(BarEffects.random(1, 0) != BarEffects.random(2, 0));
	}

	@Test
	public void burnSparksOnlyFlyWhileTheBarBurns()
	{
		final BarEffects.Particle spark = new BarEffects.Particle();
		for (int i = 0; i < BarEffects.BURN_SPARK_COUNT; i++)
		{
			assertFalse(BarEffects.burnSpark(i, -1, spark));
			assertFalse(BarEffects.burnSpark(i, BarEffects.BURN_DURATION.toMillis() + 1000, spark));
		}

		int thrown = 0;
		for (int i = 0; i < BarEffects.BURN_SPARK_COUNT; i++)
		{
			for (long millis = 0; millis <= BarEffects.BURN_DURATION.toMillis(); millis += 25)
			{
				if (BarEffects.burnSpark(i, millis, spark))
				{
					thrown++;
					assertTrue(spark.along >= 0f && spark.along <= 1f);
					// A spark starts where the edge was when it was thrown, so never ahead of the edge.
					assertTrue(spark.along <= BarEffects.burnProgress(millis) + 0.0001f);
					assertTrue(spark.y <= 0f);
				}
			}
		}
		assertTrue(thrown > 0);
	}

	@Test
	public void burnRunsTheWholeBar()
	{
		assertEquals(0f, BarEffects.burnProgress(-100), 0f);
		assertEquals(0f, BarEffects.burnProgress(0), 0f);
		assertEquals(1f, BarEffects.burnProgress(BarEffects.BURN_DURATION.toMillis()), 0f);
		assertTrue(BarEffects.burnProgress(400) < BarEffects.burnProgress(800));
	}

	@Test
	public void sparkColorsFadeOut()
	{
		assertEquals(255, BarEffects.sparkColor(0f).getAlpha());
		assertEquals(0, BarEffects.sparkColor(1f).getAlpha());
		assertTrue(BarEffects.sparkColor(0.5f).getAlpha() < BarEffects.sparkColor(0.1f).getAlpha());
	}
}

package com.ghordrin.bosshealthbar.render;

import static com.ghordrin.bosshealthbar.render.BarPainter.capRise;
import static com.ghordrin.bosshealthbar.render.BarPainter.capScale;
import static com.ghordrin.bosshealthbar.render.BarPainter.capWidth;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BarEndsTest
{
	@Test
	public void subtleEndsAtTheReferenceHeight()
	{
		assertEquals(5, capWidth(8, false, BarEnds.SUBTLE));
		assertEquals(4, capRise(8, false, BarEnds.SUBTLE));
	}

	@Test
	public void subtleEndsLeaveTheBarWiderThanClassic()
	{
		for (int height = 4; height <= 24; height++)
		{
			assertTrue(capWidth(height, false, BarEnds.SUBTLE) < capWidth(height, false, BarEnds.CLASSIC));
		}
	}

	@Test
	public void subtleEndsHaveRoomForThePointAndTips()
	{
		for (int height = 4; height <= 24; height++)
		{
			final float s = capScale(height);
			// The point plus half the outline stroke, and the curled tip above the frame line plus half the outline.
			assertTrue(capWidth(height, false, BarEnds.SUBTLE) >= 3.6f * s + 1.2f * s);
			assertTrue(capRise(height, false, BarEnds.SUBTLE) >= 2.4f * s + 1.2f * s - 0.5f);
		}
	}

	@Test
	public void subtleEndsGrowWithBarHeight()
	{
		assertTrue(capWidth(24, false, BarEnds.SUBTLE) > capWidth(8, false, BarEnds.SUBTLE));
		assertTrue(capRise(24, false, BarEnds.SUBTLE) > capRise(8, false, BarEnds.SUBTLE));
	}

	@Test
	public void labelsMatchTheDropdown()
	{
		assertEquals("Classic", BarEnds.CLASSIC.toString());
		assertEquals("Subtle", BarEnds.SUBTLE.toString());
	}
}

