import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.client.config.FontType;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

public class ItemFontsTest
{
	private static final FontType SERIF_17 = new FontType().withFamily(Font.SERIF).withSize(17);
	private static final FontType SERIF_12 = new FontType().withFamily(Font.SERIF).withSize(12);

	private static class FontsConfig implements BossHealthBarConfig
	{
		FontType font = DEFAULT_FONT;
		FontType damageNumberFont = FontType.REGULAR;
		FontType combatLevelFont = FontType.SMALL;
		FontType hitpointsFont = FontType.SMALL;
		FontType killCountFont = FontType.SMALL;
		FontType partyDefenceFont = FontType.SMALL;
		boolean smoothText = true;
		boolean showCombatLevel;
		boolean showKillCount;
		BarPosition killCountPosition = BarPosition.BOTTOM_LEFT;

		@Override
		public FontType font()
		{
			return font;
		}

		@Override
		public FontType damageNumberFont()
		{
			return damageNumberFont;
		}

		@Override
		public FontType combatLevelFont()
		{
			return combatLevelFont;
		}

		@Override
		public FontType hitpointsFont()
		{
			return hitpointsFont;
		}

		@Override
		public FontType killCountFont()
		{
			return killCountFont;
		}

		@Override
		public FontType partyDefenceFont()
		{
			return partyDefenceFont;
		}

		@Override
		public boolean smoothText()
		{
			return smoothText;
		}

		@Override
		public boolean showCombatLevel()
		{
			return showCombatLevel;
		}

		@Override
		public boolean showKillCount()
		{
			return showKillCount;
		}

		@Override
		public BarPosition killCountPosition()
		{
			return killCountPosition;
		}
	}

	private static BarTextPainter painter(FontsConfig config)
	{
		final BarTextPainter painter = new BarTextPainter(null, config);
		painter.updateFonts();
		painter.updateRows(false, false, false, false, false);
		return painter;
	}

	// The old look for a Serif 17 name, as the one-time migration sets it up.
	private static FontsConfig migratedSerif()
	{
		final FontsConfig config = new FontsConfig();
		config.font = SERIF_17;
		config.damageNumberFont = SERIF_17;
		config.combatLevelFont = SERIF_12;
		config.hitpointsFont = SERIF_12;
		config.killCountFont = SERIF_12;
		config.partyDefenceFont = SERIF_12;
		return config;
	}

	@Test
	public void migratedSmallTextRowsKeepTheirOldHeightAtEverySize()
	{
		for (int size = 8; size <= 40; size++)
		{
			final FontType name = new FontType().withFamily(Font.SERIF).withSize(size);
			final FontType small = ConfigMigrations.smallTextFont(name);
			final FontsConfig config = new FontsConfig();
			config.font = name;
			config.damageNumberFont = name;
			config.combatLevelFont = small;
			config.hitpointsFont = small;
			config.killCountFont = small;
			config.partyDefenceFont = small;
			// The old row was as tall as the name font. At the smallest sizes the text reached past that,
			// and the row now grows to fit it.
			final BarTextPainter painter = painter(config);
			assertEquals("size " + size, Math.max(size, painter.rowBaseline(BarPosition.Row.BOTTOM)), painter.rowHeight(BarPosition.Row.BOTTOM));
			if (size >= 10)
			{
				assertEquals("size " + size, size, painter.rowHeight(BarPosition.Row.BOTTOM));
			}
		}
	}

	@Test
	public void theTallestItemSetsTheRowBaselineAndHeight()
	{
		final BarPosition[] positions = new BarPosition[ITEM_COUNT];
		Arrays.fill(positions, BarPosition.TOP_LEFT);
		final boolean[] available = new boolean[ITEM_COUNT];
		available[NAME] = true;
		available[KILL_COUNT] = true;
		final int[] above = new int[ITEM_COUNT];
		final int[] below = new int[ITEM_COUNT];
		above[NAME] = 18;
		below[NAME] = 6;
		above[KILL_COUNT] = 30;
		below[KILL_COUNT] = 2;

		assertEquals(30, BarTextPainter.rowBaseline(positions, available, BarPosition.Row.TOP, above));
		assertEquals(36, BarTextPainter.rowHeight(positions, available, BarPosition.Row.TOP, above, below));
		assertEquals(0, BarTextPainter.rowHeight(positions, available, BarPosition.Row.BOTTOM, above, below));
	}

	@Test
	public void fontsAreReadPerItem()
	{
		final FontsConfig config = new FontsConfig();
		config.partyDefenceFont = SERIF_12;
		final FontType[] fonts = new FontType[ITEM_COUNT];
		BarFonts.readItemFonts(config, fonts);
		assertSame(BossHealthBarConfig.DEFAULT_FONT, fonts[NAME]);
		assertSame(FontType.REGULAR, fonts[DAMAGE_NUMBER]);
		assertSame(FontType.SMALL, fonts[HITPOINTS]);
		assertSame(SERIF_12, fonts[PARTY_DEFENCE]);
		assertSame(SERIF_12, fonts[MAGIC_DEFENCE]);
		assertSame(FontType.SMALL, fonts[DRAIN_CAP]);
		assertSame(FontType.SMALL, fonts[BarTextPainter.FIGHT_TIMER]);
	}

	@Test
	public void defaultFontsLookAsBefore()
	{
		final FontsConfig config = new FontsConfig();
		config.showCombatLevel = true;
		final BarTextPainter painter = painter(config);
		final String small = FontManager.getRunescapeSmallFont().getFamily();

		assertEquals(FontManager.getRunescapeFont().getFamily(), painter.fonts().font(NAME).getFamily());
		assertEquals(16, painter.fonts().font(NAME).getSize());
		assertEquals(16, painter.fonts().font(DAMAGE_NUMBER).getSize());
		assertEquals(small, painter.fonts().font(HITPOINTS).getFamily());
		assertEquals(16, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(small, painter.fonts().levelFont().getFamily());
		assertEquals(24, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(16, painter.rowHeight(BarPosition.Row.BOTTOM));
		assertEquals(18, painter.rowBaseline(BarPosition.Row.TOP));
		assertEquals(12, painter.rowBaseline(BarPosition.Row.BOTTOM));
	}

	@Test
	public void migratedSerifLooksAsBefore()
	{
		final FontsConfig config = migratedSerif();
		config.showCombatLevel = true;
		final BarTextPainter painter = painter(config);

		// The old code put a row of small text at the small font's ascent + 1, measured with these hints.
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		final int smallAscent = graphics.getFontMetrics(FontManager.getFallbackFont(Font.SERIF, Font.PLAIN, 12)).getAscent();
		graphics.dispose();

		assertEquals(17, painter.fonts().font(NAME).getSize());
		assertEquals(12, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(12, painter.fonts().levelFont().getSize());
		assertEquals(26, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(17, painter.rowHeight(BarPosition.Row.BOTTOM));
		assertEquals(20, painter.rowBaseline(BarPosition.Row.TOP));
		assertEquals(smallAscent + 1, painter.rowBaseline(BarPosition.Row.BOTTOM));
	}

	@Test
	public void theNameFontSizeOnlyChangesTheName()
	{
		final FontsConfig config = new FontsConfig();
		config.font = FontType.REGULAR.withSize(24);
		final BarTextPainter painter = painter(config);

		assertEquals(24, painter.fonts().font(NAME).getSize());
		assertEquals(16, painter.fonts().font(DAMAGE_NUMBER).getSize());
		assertEquals(16, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(36, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(16, painter.rowHeight(BarPosition.Row.BOTTOM));
	}

	@Test
	public void rowsGrowToFitLargerFonts()
	{
		final FontsConfig config = new FontsConfig();
		config.hitpointsFont = FontType.SMALL.withSize(32);
		config.showKillCount = true;
		config.killCountPosition = BarPosition.TOP_CENTER;
		config.killCountFont = FontType.SMALL.withSize(40);
		final BarTextPainter painter = painter(config);

		assertEquals(32, painter.fonts().font(HITPOINTS).getSize());
		assertEquals(40, painter.fonts().font(KILL_COUNT).getSize());
		assertEquals(40, painter.rowHeight(BarPosition.Row.TOP));
		assertEquals(32, painter.rowHeight(BarPosition.Row.BOTTOM));
	}

	@Test
	public void iconsFollowTheirItemsFont()
	{
		final Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		final FontMetrics normal = graphics.getFontMetrics(FontManager.getRunescapeSmallFont());
		final FontMetrics large = graphics.getFontMetrics(FontManager.getRunescapeSmallFont().deriveFont(32f));
		graphics.dispose();

		assertTrue(BarTextPainter.itemIconSize(large) > BarTextPainter.itemIconSize(normal));
		assertEquals(Math.round((normal.getAscent() + 1) * 1.3f), BarTextPainter.itemIconSize(normal));
	}

	@Test
	public void onlyChangedFontsAreRebuilt()
	{
		final FontsConfig config = new FontsConfig();
		final BarTextPainter painter = painter(config);
		final Font name = painter.fonts().font(NAME);
		final Font hitpoints = painter.fonts().font(HITPOINTS);
		final Font killCount = painter.fonts().font(KILL_COUNT);

		painter.updateFonts();
		assertSame(name, painter.fonts().font(NAME));
		assertSame(hitpoints, painter.fonts().font(HITPOINTS));

		config.hitpointsFont = FontType.SMALL.withSize(24);
		painter.updateFonts();
		assertEquals(24, painter.fonts().font(HITPOINTS).getSize());
		assertSame(killCount, painter.fonts().font(KILL_COUNT));
		assertSame(name, painter.fonts().font(NAME));

		// Smooth text only changes how the fonts are measured and drawn.
		config.smoothText = false;
		painter.updateFonts();
		assertSame(killCount, painter.fonts().font(KILL_COUNT));

		config.killCountFont = FontType.SMALL.withBold(true);
		painter.updateFonts();
		assertTrue(painter.fonts().font(KILL_COUNT).isBold());
		config.killCountFont = FontType.SMALL.withItalic(true);
		painter.updateFonts();
		assertFalse(painter.fonts().font(KILL_COUNT).isBold());
		assertTrue(painter.fonts().font(KILL_COUNT).isItalic());
		assertSame(name, painter.fonts().font(NAME));
	}
}

package com.ghordrin.bosshealthbar.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import com.ghordrin.bosshealthbar.tracking.DamageTracker;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class TextOutlineTest
{
	private static final Color FILL = new Color(0x40C0FF);
	private static final String TEXT = "1234";

	private static class OutlineConfig implements BossHealthBarConfig
	{
		TextOutline outline = TextOutline.SHADOW;

		@Override
		public TextOutline textOutline()
		{
			return outline;
		}

		@Override
		public boolean smoothText()
		{
			return false;
		}
	}

	@Test
	public void theDefaultIsAShadow()
	{
		assertEquals(TextOutline.SHADOW, new BossHealthBarConfig()
		{
		}.textOutline());
	}

	@Test
	public void everyEdgeDrawsTheTextItselfInTheSamePlace()
	{
		List<Point> expected = null;
		for (TextOutline outline : TextOutline.values())
		{
			final OutlineConfig config = new OutlineConfig();
			config.outline = outline;
			final BarTextPainter painter = new BarTextPainter(new DamageTracker(), config);
			painter.updateFonts();

			final BufferedImage image = new BufferedImage(120, 40, BufferedImage.TYPE_INT_ARGB);
			final Graphics2D graphics = image.createGraphics();
			painter.applyTextHints(graphics);
			painter.drawHitpointsStyleText(graphics, TEXT, 20, 25, FILL);
			graphics.dispose();

			final List<Point> pixels = filledPixels(image);
			assertTrue(outline.name() + " drew nothing", !pixels.isEmpty());
			if (expected == null)
			{
				expected = pixels;
			}
			assertEquals(outline.name(), expected, pixels);
		}
	}

	@Test
	public void theTextMetricsDoNotDependOnTheEdge()
	{
		Integer width = null;
		for (TextOutline outline : TextOutline.values())
		{
			final OutlineConfig config = new OutlineConfig();
			config.outline = outline;
			final BarTextPainter painter = new BarTextPainter(new DamageTracker(), config);
			painter.updateFonts();
			final int stringWidth = painter.hitpointsMetrics().stringWidth(TEXT);
			if (width == null)
			{
				width = stringWidth;
			}
			assertEquals(outline.name(), width.intValue(), stringWidth);
		}
	}

	// Where the fill color itself landed. The edge is drawn under it, so these pixels are the text.
	private static List<Point> filledPixels(BufferedImage image)
	{
		final List<Point> pixels = new ArrayList<>();
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if (image.getRGB(x, y) == (FILL.getRGB() | 0xFF000000))
				{
					pixels.add(new Point(x, y));
				}
			}
		}
		return pixels;
	}
}

package com.ghordrin.bosshealthbar.theme;

import static org.junit.Assert.assertEquals;
import com.ghordrin.bosshealthbar.config.BossHealthBarConfig;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import org.junit.Test;

public class CustomColorsTest
{
	private static final ThemeColors COLORS = ThemeColors.builder()
		.fillHigh(new Color(1))
		.fillLow(new Color(2))
		.trail(new Color(3))
		.frame(new Color(4))
		.text(new Color(5))
		.levelText(new Color(6))
		.hitpointsText(new Color(7))
		.defeatedText(new Color(8))
		.build();

	@Test
	public void everyCustomColorKeyGetsItsOwnColor()
	{
		final Map<String, Color> keyed = CustomColors.keyedColors(COLORS);
		// Saved key names: changing one resets that colour for every user.
		assertEquals(Arrays.asList("customFillHighColor", "customFillLowColor", "customTrailColor", "customFrameColor",
			"customTextColor", "customLevelTextColor", "customHitpointsTextColor", "customDefeatedTextColor"),
			new ArrayList<>(keyed.keySet()));
		assertEquals(Arrays.asList(new Color(1), new Color(2), new Color(3), new Color(4), new Color(5), new Color(6),
			new Color(7), new Color(8)), new ArrayList<>(keyed.values()));
	}

	@Test
	public void theCustomThemeReadsEveryCustomColor()
	{
		final BossHealthBarConfig config = new BossHealthBarConfig()
		{
			@Override
			public Color customFillHighColor()
			{
				return COLORS.getFillHigh();
			}

			@Override
			public Color customFillLowColor()
			{
				return COLORS.getFillLow();
			}

			@Override
			public Color customTrailColor()
			{
				return COLORS.getTrail();
			}

			@Override
			public Color customFrameColor()
			{
				return COLORS.getFrame();
			}

			@Override
			public Color customTextColor()
			{
				return COLORS.getText();
			}

			@Override
			public Color customLevelTextColor()
			{
				return COLORS.getLevelText();
			}

			@Override
			public Color customHitpointsTextColor()
			{
				return COLORS.getHitpointsText();
			}

			@Override
			public Color customDefeatedTextColor()
			{
				return COLORS.getDefeatedText();
			}
		};
		assertEquals(COLORS, CustomColors.fromConfig(config));
	}
}

